window.KS4SRC["land-use"] = {"common_mistake": "Destroying a peat bog harms the environment in TWO ways, not one: it reduces biodiversity (habitat lost) AND releases carbon dioxide (stored carbon escapes as the peat decays or is burned). Many students only mention one. Peat is extracted mainly for COMPOST, not just as a fuel.", "key_note": "Humans reduce land for other species by building, quarrying, farming and dumping waste. Peat bogs store carbon and are rich habitats. Extracting peat for compost/fuel destroys the habitat (lowering biodiversity) and releases CO\u2082 when peat decays or burns. Use peat-free compost.", "matching": {"instruction": "Sort each statement into a human land use or a consequence of destroying peat bogs.", "pairs": [["Human land use", "Building houses, factories and roads"], ["Human land use", "Quarrying rock and minerals"], ["Human land use", "Farming crops and livestock"], ["Consequence of peat destruction", "Carbon dioxide released as peat decays or burns"], ["Consequence of peat destruction", "Loss of a specialised habitat"], ["Consequence of peat destruction", "Reduced biodiversity of bog species"]], "title": "Land Use: Cause or Consequence?"}, "quiz": {"CF": [{"opts": [["Peat stores carbon from partly-decayed plants; decay or burning releases it as CO\u2082", true], ["Peat is made of pure carbon dioxide gas", false], ["Machines used to dig peat run on petrol", false], ["Peat reflects sunlight, warming the air", false]], "q": "Why does draining and extracting peat release carbon dioxide?", "wrong_explanations": {"1": "Peat is partly-decayed plant material that locked away carbon; when it decays in air or is burned, that carbon is released as CO\u2082.", "2": "Peat is solid plant material, not CO\u2082 gas \u2014 the CO\u2082 is released only when the stored carbon reacts with oxygen.", "3": "The machinery is a minor factor; the main release is the carbon stored in the peat itself escaping as CO\u2082."}}, {"opts": [["Buying peat-free compost for gardens", true], ["Extracting peat faster so it is used up sooner", false], ["Burning peat instead of using it as compost", false], ["Draining more bogs to create farmland", false]], "q": "Which single change would best protect peat bog biodiversity?", "wrong_explanations": {"1": "If gardeners choose peat-free compost, demand for peat falls, so fewer bogs are destroyed and their biodiversity is protected.", "2": "Extracting peat faster destroys the habitat sooner \u2014 the opposite of protecting it.", "3": "Burning peat still destroys the bog and releases CO\u2082."}}], "CH": [{"opts": [["Peat stores carbon from partly-decayed plants; decay or burning releases it as CO\u2082", true], ["Peat is made of pure carbon dioxide gas", false], ["Machines used to dig peat run on petrol", false], ["Peat reflects sunlight, warming the air", false]], "q": "Why does draining and extracting peat release carbon dioxide?", "wrong_explanations": {"1": "Peat is partly-decayed plant material that locked away carbon; when it decays in air or is burned, that carbon is released as CO\u2082.", "2": "Peat is solid plant material, not CO\u2082 gas \u2014 the CO\u2082 is released only when the stored carbon reacts with oxygen.", "3": "The machinery is a minor factor; the main release is the carbon stored in the peat itself escaping as CO\u2082."}}, {"opts": [["Buying peat-free compost for gardens", true], ["Extracting peat faster so it is used up sooner", false], ["Burning peat instead of using it as compost", false], ["Draining more bogs to create farmland", false]], "q": "Which single change would best protect peat bog biodiversity?", "wrong_explanations": {"1": "If gardeners choose peat-free compost, demand for peat falls, so fewer bogs are destroyed and their biodiversity is protected.", "2": "Extracting peat faster destroys the habitat sooner \u2014 the opposite of protecting it.", "3": "Burning peat still destroys the bog and releases CO\u2082."}}], "TF": [{"opts": [["Peat stores carbon from partly-decayed plants; decay or burning releases it as CO\u2082", true], ["Peat is made of pure carbon dioxide gas", false], ["Machines used to dig peat run on petrol", false], ["Peat reflects sunlight, warming the air", false]], "q": "Why does draining and extracting peat release carbon dioxide?", "wrong_explanations": {"1": "Peat is partly-decayed plant material that locked away carbon; when it decays in air or is burned, that carbon is released as CO\u2082.", "2": "Peat is solid plant material, not CO\u2082 gas \u2014 the CO\u2082 is released only when the stored carbon reacts with oxygen.", "3": "The machinery is a minor factor; the main release is the carbon stored in the peat itself escaping as CO\u2082."}}, {"opts": [["Buying peat-free compost for gardens", true], ["Extracting peat faster so it is used up sooner", false], ["Burning peat instead of using it as compost", false], ["Draining more bogs to create farmland", false]], "q": "Which single change would best protect peat bog biodiversity?", "wrong_explanations": {"1": "If gardeners choose peat-free compost, demand for peat falls, so fewer bogs are destroyed and their biodiversity is protected.", "2": "Extracting peat faster destroys the habitat sooner \u2014 the opposite of protecting it.", "3": "Burning peat still destroys the bog and releases CO\u2082."}}], "TH": [{"opts": [["Peat stores carbon from partly-decayed plants; decay or burning releases it as CO\u2082", true], ["Peat is made of pure carbon dioxide gas", false], ["Machines used to dig peat run on petrol", false], ["Peat reflects sunlight, warming the air", false]], "q": "Why does draining and extracting peat release carbon dioxide?", "wrong_explanations": {"1": "Peat is partly-decayed plant material that locked away carbon; when it decays in air or is burned, that carbon is released as CO\u2082.", "2": "Peat is solid plant material, not CO\u2082 gas \u2014 the CO\u2082 is released only when the stored carbon reacts with oxygen.", "3": "The machinery is a minor factor; the main release is the carbon stored in the peat itself escaping as CO\u2082."}}, {"opts": [["Buying peat-free compost for gardens", true], ["Extracting peat faster so it is used up sooner", false], ["Burning peat instead of using it as compost", false], ["Draining more bogs to create farmland", false]], "q": "Which single change would best protect peat bog biodiversity?", "wrong_explanations": {"1": "If gardeners choose peat-free compost, demand for peat falls, so fewer bogs are destroyed and their biodiversity is protected.", "2": "Extracting peat faster destroys the habitat sooner \u2014 the opposite of protecting it.", "3": "Burning peat still destroys the bog and releases CO\u2082."}}]}, "summary": "Describe how humans reduce land available for other organisms, and explain why destroying peat bogs harms biodiversity and releases carbon dioxide.", "theory": [{"content": "Humans REDUCE the amount of land available for other plants and animals.\n\nWe use land for:\nBUILDING \u2014 houses, factories, roads.\nQUARRYING \u2014 digging out rock and minerals.\nFARMING \u2014 growing crops and keeping animals.\nDUMPING WASTE \u2014 landfill sites.\n\nEvery time land is used for these, HABITATS are destroyed and there is less space for wild species \u2014 so biodiversity falls.", "heading": "How humans use up land"}, {"content": "PEAT BOGS are waterlogged areas where dead plants do not fully decay (there is not enough oxygen for decomposers).\n\nOver thousands of years the partly-decayed plants build up as PEAT.\n\nBecause the plants never fully decayed, peat STORES a large amount of CARBON.\n\nPeat bogs are an important HABITAT for many specialised plants, animals and microorganisms.", "heading": "What peat bogs are"}, {"content": "Peat is dug up (extracted) to sell as COMPOST for gardens and for commercial food production, and it can be burned as a fuel.\n\nDestroying peat bogs:\nREDUCES the area of this habitat \u2192 the biodiversity of the species living there DECREASES.\nReleases CARBON DIOXIDE \u2014 when peat is drained and decays, or is burned, the stored carbon is released as CO\u2082, adding to global warming.\n\nUsing peat-free compost helps protect peat bogs.", "heading": "Why destroying peat bogs is a problem"}]};
window.KS4SRC["metals-non-metals"] = {"common_mistake": "Graphite and graphene are non-metals that conduct electricity \u2014 they are exceptions. Most non-metals do not conduct, but graphite has delocalised electrons between its layers. Don't say 'all non-metals don't conduct' \u2014 say 'non-metals generally don't conduct, except graphite and graphene'.", "key_note": "Metals: good conductors, high melting points, malleable, ductile, form positive ions, basic oxides. Non-metals: poor conductors (except graphite), low melting points, brittle, form negative ions, acidic oxides. Metallic character decreases across a period and increases down a group.", "matching": {"instruction": "Sort each property into metals or non-metals.", "pairs": [["Metal", "Good conductor of electricity \u2014 delocalised electrons carry charge"], ["Non-metal", "Poor conductor of electricity \u2014 no free electrons (except graphite)"], ["Metal", "Malleable \u2014 can be hammered into sheets without shattering"], ["Non-metal", "Brittle solid \u2014 shatters when struck"], ["Metal", "Forms positive ions by losing electrons in reactions"], ["Non-metal", "Forms acidic oxides \u2014 e.g. CO\u2082 dissolves in water to form carbonic acid"]], "title": "Metal or Non-metal Property?"}, "quiz": {"CF": [{"opts": [["Metals have delocalised (free) electrons that can move through the structure and carry charge", true], ["Metal atoms are larger, so electrons move more easily", false], ["Metals have more protons than non-metals, creating stronger positive charge", false], ["Metal compounds dissolve in water to release ions that carry charge", false]], "q": "Why are metals good conductors of electricity?", "wrong_explanations": {"1": "Atomic size does not determine conductivity \u2014 it is the presence of FREE electrons, not large atoms, that allows charge to flow.", "2": "Proton count determines the element, not conductivity. Non-metals also have many protons but are poor conductors.", "3": "Solid metals conduct electricity \u2014 not dissolved ions. Ionic conductivity in solution is different from metallic conductivity in a solid."}}, {"opts": [["Non-metal \u2014 non-metal oxides form acidic solutions when dissolved in water", true], ["Metal \u2014 metal oxides are always basic", false], ["Metalloid \u2014 SO\u2082 is both acidic and basic", false], ["It could be either \u2014 the acidity of its oxide doesn't indicate the type of element", false]], "q": "Sulfur dioxide (SO\u2082) dissolves in water to form an acidic solution. Is sulfur a metal or non-metal?", "wrong_explanations": {"1": "Metal oxides are BASIC \u2014 they neutralise acids. SO\u2082 forms an acidic solution, which is the behaviour of NON-METAL oxides.", "2": "SO\u2082 is not amphoteric (both acidic and basic) \u2014 it is distinctly acidic. Sulfur is clearly a non-metal.", "3": "The type of oxide (acidic or basic) is a reliable indicator of whether the element is a metal or non-metal."}}], "CH": [{"opts": [["Metals have delocalised (free) electrons that can move through the structure and carry charge", true], ["Metal atoms are larger, so electrons move more easily", false], ["Metals have more protons than non-metals, creating stronger positive charge", false], ["Metal compounds dissolve in water to release ions that carry charge", false]], "q": "Why are metals good conductors of electricity?", "wrong_explanations": {"1": "Atomic size does not determine conductivity \u2014 it is the presence of FREE electrons, not large atoms, that allows charge to flow.", "2": "Proton count determines the element, not conductivity. Non-metals also have many protons but are poor conductors.", "3": "Solid metals conduct electricity \u2014 not dissolved ions. Ionic conductivity in solution is different from metallic conductivity in a solid."}}, {"opts": [["Non-metal \u2014 non-metal oxides form acidic solutions when dissolved in water", true], ["Metal \u2014 metal oxides are always basic", false], ["Metalloid \u2014 SO\u2082 is both acidic and basic", false], ["It could be either \u2014 the acidity of its oxide doesn't indicate the type of element", false]], "q": "Sulfur dioxide (SO\u2082) dissolves in water to form an acidic solution. Is sulfur a metal or non-metal?", "wrong_explanations": {"1": "Metal oxides are BASIC \u2014 they neutralise acids. SO\u2082 forms an acidic solution, which is the behaviour of NON-METAL oxides.", "2": "SO\u2082 is not amphoteric (both acidic and basic) \u2014 it is distinctly acidic. Sulfur is clearly a non-metal.", "3": "The type of oxide (acidic or basic) is a reliable indicator of whether the element is a metal or non-metal."}}], "TF": [{"opts": [["Metals have delocalised (free) electrons that can move through the structure and carry charge", true], ["Metal atoms are larger, so electrons move more easily", false], ["Metals have more protons than non-metals, creating stronger positive charge", false], ["Metal compounds dissolve in water to release ions that carry charge", false]], "q": "Why are metals good conductors of electricity?", "wrong_explanations": {"1": "Atomic size does not determine conductivity \u2014 it is the presence of FREE electrons, not large atoms, that allows charge to flow.", "2": "Proton count determines the element, not conductivity. Non-metals also have many protons but are poor conductors.", "3": "Solid metals conduct electricity \u2014 not dissolved ions. Ionic conductivity in solution is different from metallic conductivity in a solid."}}, {"opts": [["Non-metal \u2014 non-metal oxides form acidic solutions when dissolved in water", true], ["Metal \u2014 metal oxides are always basic", false], ["Metalloid \u2014 SO\u2082 is both acidic and basic", false], ["It could be either \u2014 the acidity of its oxide doesn't indicate the type of element", false]], "q": "Sulfur dioxide (SO\u2082) dissolves in water to form an acidic solution. Is sulfur a metal or non-metal?", "wrong_explanations": {"1": "Metal oxides are BASIC \u2014 they neutralise acids. SO\u2082 forms an acidic solution, which is the behaviour of NON-METAL oxides.", "2": "SO\u2082 is not amphoteric (both acidic and basic) \u2014 it is distinctly acidic. Sulfur is clearly a non-metal.", "3": "The type of oxide (acidic or basic) is a reliable indicator of whether the element is a metal or non-metal."}}], "TH": [{"opts": [["Metals have delocalised (free) electrons that can move through the structure and carry charge", true], ["Metal atoms are larger, so electrons move more easily", false], ["Metals have more protons than non-metals, creating stronger positive charge", false], ["Metal compounds dissolve in water to release ions that carry charge", false]], "q": "Why are metals good conductors of electricity?", "wrong_explanations": {"1": "Atomic size does not determine conductivity \u2014 it is the presence of FREE electrons, not large atoms, that allows charge to flow.", "2": "Proton count determines the element, not conductivity. Non-metals also have many protons but are poor conductors.", "3": "Solid metals conduct electricity \u2014 not dissolved ions. Ionic conductivity in solution is different from metallic conductivity in a solid."}}, {"opts": [["Non-metal \u2014 non-metal oxides form acidic solutions when dissolved in water", true], ["Metal \u2014 metal oxides are always basic", false], ["Metalloid \u2014 SO\u2082 is both acidic and basic", false], ["It could be either \u2014 the acidity of its oxide doesn't indicate the type of element", false]], "q": "Sulfur dioxide (SO\u2082) dissolves in water to form an acidic solution. Is sulfur a metal or non-metal?", "wrong_explanations": {"1": "Metal oxides are BASIC \u2014 they neutralise acids. SO\u2082 forms an acidic solution, which is the behaviour of NON-METAL oxides.", "2": "SO\u2082 is not amphoteric (both acidic and basic) \u2014 it is distinctly acidic. Sulfur is clearly a non-metal.", "3": "The type of oxide (acidic or basic) is a reliable indicator of whether the element is a metal or non-metal."}}]}, "summary": "Compare the properties of metals and non-metals and explain them in terms of structure and bonding.", "theory": [{"content": "Most elements are METALS \u2014 they are found on the left and in the centre of the periodic table.\n\nTypical physical properties of metals:\nGOOD CONDUCTORS of electricity and heat \u2014 delocalised electrons carry charge and energy.\nHIGH MELTING AND BOILING POINTS \u2014 strong metallic bonds.\nSHINY (lustrous) appearance when cut or polished.\nMALLEABLE \u2014 can be hammered into sheets without breaking.\nDUCTILE \u2014 can be drawn into wires.\nSOLID at room temperature \u2014 except mercury (Hg), which is a liquid.\nHIGH DENSITY in most cases.\n\nChemical properties of metals:\nFORM POSITIVE IONS \u2014 lose outer electrons in reactions.\nREACT with oxygen to form METAL OXIDES (these are BASIC \u2014 they neutralise acids).\nMany react with water and acids to produce hydrogen gas.", "heading": "Properties of Metals"}, {"content": "NON-METALS are found on the right side of the periodic table.\n\nTypical physical properties of non-metals:\nPOOR CONDUCTORS of electricity (except graphite and graphene).\nLOW MELTING AND BOILING POINTS \u2014 weak forces between molecules.\nBRITTLE when solid \u2014 cannot be bent or drawn into wires.\nLow density generally.\nMany are GASES at room temperature (O\u2082, N\u2082, Cl\u2082, H\u2082, etc.).\nSome are SOLIDS (carbon, sulfur, phosphorus, iodine).\nBromine (Br\u2082) is a liquid at room temperature.\n\nChemical properties of non-metals:\nFORM NEGATIVE IONS \u2014 gain electrons (or share in covalent bonds).\nREACT with oxygen to form NON-METAL OXIDES (these are ACIDIC \u2014 they dissolve in water to form acids).", "heading": "Properties of Non-metals"}, {"content": "A useful comparison table:\n\nElectrical conductivity:\nMETAL: Good conductor (delocalised electrons).\nNON-METAL: Poor conductor (no free electrons) \u2014 EXCEPT graphite.\n\nMelting/boiling point:\nMETAL: Generally high \u2014 strong metallic bonds.\nNON-METAL: Generally low \u2014 weak intermolecular forces.\n\nMalleability/ductility:\nMETAL: Malleable and ductile.\nNON-METAL: Brittle.\n\nIon formation:\nMETAL: Forms POSITIVE ions (loses electrons).\nNON-METAL: Forms NEGATIVE ions (gains electrons).\n\nOxide type:\nMETAL: Basic oxides (e.g. MgO, Fe\u2082O\u2083).\nNON-METAL: Acidic oxides (e.g. CO\u2082, SO\u2082, NO\u2082).\n\nSome elements (like silicon) are METALLOIDS \u2014 they have properties between metals and non-metals. Silicon conducts electricity but is brittle \u2014 it is a semiconductor, used in electronics.", "heading": "Key Differences \u2014 Metals vs Non-metals"}]};
window.KS4SRC["reactivity-series"] = {"common_mistake": "A metal can only displace another metal that is BELOW it in the reactivity series. Copper cannot displace iron from iron sulfate \u2014 copper is less reactive than iron. The more reactive metal always displaces the less reactive one, not the other way around.", "equations": ["Fe + CuSO\u2084 \u2192 FeSO\u2084 + Cu  (displacement)", "Metal + oxygen \u2192 metal oxide", "Metal + water \u2192 metal hydroxide + hydrogen", "Metal + acid \u2192 salt + hydrogen"], "higher": "Explain reactivity in terms of ionisation energy \u2014 more reactive metals have lower ionisation energies and lose electrons more easily. Write ionic equations for displacement: Fe + Cu\u00b2\u207a(aq) \u2192 Fe\u00b2\u207a(aq) + Cu. Recognise spectator ions and write net ionic equations.", "key_note": "Reactivity series: K, Na, Li, Ca, Mg, Al, (C), Zn, Fe, Sn, Pb, (H), Cu, Ag, Au, Pt. More reactive metal displaces less reactive from solution or oxide. Evidence from reactions with water, acid and displacement reactions.", "matching": {"instruction": "Predict whether each displacement reaction occurs.", "pairs": [["Reaction occurs", "Zinc + copper sulfate \u2192 zinc sulfate + copper (Zn more reactive than Cu)"], ["No reaction", "Copper + zinc sulfate \u2014 copper is LESS reactive than zinc"], ["Reaction occurs", "Magnesium + iron sulfate \u2192 magnesium sulfate + iron (Mg more reactive than Fe)"], ["No reaction", "Iron + magnesium sulfate \u2014 iron is LESS reactive than magnesium"], ["Reaction occurs", "Iron + copper sulfate \u2192 iron sulfate + copper (Fe more reactive than Cu)"]], "title": "Displacement \u2014 Reaction or No Reaction?"}, "quiz": {"CF": [{"opts": [["The blue solution fades and copper metal deposits on the zinc \u2014 zinc displaces copper", true], ["No change \u2014 zinc and copper have similar reactivity", false], ["The zinc dissolves and the solution turns orange", false], ["Zinc sulfate crystals form in the blue solution", false]], "q": "A strip of zinc is placed in copper sulfate solution. What is observed?", "wrong_explanations": {"1": "Zinc IS more reactive than copper \u2014 a reaction occurs. The solution changes from blue (Cu\u00b2\u207a) to colourless/pale (Zn\u00b2\u207a).", "2": "The solution turns pale/colourless as Cu\u00b2\u207a ions are replaced by Zn\u00b2\u207a \u2014 orange is not the colour of any of these solutions.", "3": "Zinc sulfate is formed in solution (dissolved) \u2014 it doesn't crystallise out immediately under these conditions."}}, {"opts": [["Copper is BELOW hydrogen in the reactivity series \u2014 it cannot displace hydrogen from the acid", true], ["Copper is too dense to react with liquids", false], ["Hydrochloric acid is not strong enough to react with any metals", false], ["Copper reacts with acid but the product is insoluble", false]], "q": "Why does copper not react with dilute hydrochloric acid?", "wrong_explanations": {"1": "Density doesn't determine reactivity \u2014 gold is denser than magnesium but far less reactive.", "2": "HCl reacts with many metals \u2014 magnesium, zinc, iron all react vigorously with HCl. Only metals BELOW hydrogen in the series don't react.", "3": "Copper doesn't react with dilute HCl at all \u2014 it doesn't produce any product."}}], "CH": [{"opts": [["The blue solution fades and copper metal deposits on the zinc \u2014 zinc displaces copper", true], ["No change \u2014 zinc and copper have similar reactivity", false], ["The zinc dissolves and the solution turns orange", false], ["Zinc sulfate crystals form in the blue solution", false]], "q": "A strip of zinc is placed in copper sulfate solution. What is observed?", "wrong_explanations": {"1": "Zinc IS more reactive than copper \u2014 a reaction occurs. The solution changes from blue (Cu\u00b2\u207a) to colourless/pale (Zn\u00b2\u207a).", "2": "The solution turns pale/colourless as Cu\u00b2\u207a ions are replaced by Zn\u00b2\u207a \u2014 orange is not the colour of any of these solutions.", "3": "Zinc sulfate is formed in solution (dissolved) \u2014 it doesn't crystallise out immediately under these conditions."}}, {"opts": [["Copper is BELOW hydrogen in the reactivity series \u2014 it cannot displace hydrogen from the acid", true], ["Copper is too dense to react with liquids", false], ["Hydrochloric acid is not strong enough to react with any metals", false], ["Copper reacts with acid but the product is insoluble", false]], "q": "Why does copper not react with dilute hydrochloric acid?", "wrong_explanations": {"1": "Density doesn't determine reactivity \u2014 gold is denser than magnesium but far less reactive.", "2": "HCl reacts with many metals \u2014 magnesium, zinc, iron all react vigorously with HCl. Only metals BELOW hydrogen in the series don't react.", "3": "Copper doesn't react with dilute HCl at all \u2014 it doesn't produce any product."}}], "TF": [{"opts": [["The blue solution fades and copper metal deposits on the zinc \u2014 zinc displaces copper", true], ["No change \u2014 zinc and copper have similar reactivity", false], ["The zinc dissolves and the solution turns orange", false], ["Zinc sulfate crystals form in the blue solution", false]], "q": "A strip of zinc is placed in copper sulfate solution. What is observed?", "wrong_explanations": {"1": "Zinc IS more reactive than copper \u2014 a reaction occurs. The solution changes from blue (Cu\u00b2\u207a) to colourless/pale (Zn\u00b2\u207a).", "2": "The solution turns pale/colourless as Cu\u00b2\u207a ions are replaced by Zn\u00b2\u207a \u2014 orange is not the colour of any of these solutions.", "3": "Zinc sulfate is formed in solution (dissolved) \u2014 it doesn't crystallise out immediately under these conditions."}}, {"opts": [["Copper is BELOW hydrogen in the reactivity series \u2014 it cannot displace hydrogen from the acid", true], ["Copper is too dense to react with liquids", false], ["Hydrochloric acid is not strong enough to react with any metals", false], ["Copper reacts with acid but the product is insoluble", false]], "q": "Why does copper not react with dilute hydrochloric acid?", "wrong_explanations": {"1": "Density doesn't determine reactivity \u2014 gold is denser than magnesium but far less reactive.", "2": "HCl reacts with many metals \u2014 magnesium, zinc, iron all react vigorously with HCl. Only metals BELOW hydrogen in the series don't react.", "3": "Copper doesn't react with dilute HCl at all \u2014 it doesn't produce any product."}}], "TH": [{"opts": [["The blue solution fades and copper metal deposits on the zinc \u2014 zinc displaces copper", true], ["No change \u2014 zinc and copper have similar reactivity", false], ["The zinc dissolves and the solution turns orange", false], ["Zinc sulfate crystals form in the blue solution", false]], "q": "A strip of zinc is placed in copper sulfate solution. What is observed?", "wrong_explanations": {"1": "Zinc IS more reactive than copper \u2014 a reaction occurs. The solution changes from blue (Cu\u00b2\u207a) to colourless/pale (Zn\u00b2\u207a).", "2": "The solution turns pale/colourless as Cu\u00b2\u207a ions are replaced by Zn\u00b2\u207a \u2014 orange is not the colour of any of these solutions.", "3": "Zinc sulfate is formed in solution (dissolved) \u2014 it doesn't crystallise out immediately under these conditions."}}, {"opts": [["Copper is BELOW hydrogen in the reactivity series \u2014 it cannot displace hydrogen from the acid", true], ["Copper is too dense to react with liquids", false], ["Hydrochloric acid is not strong enough to react with any metals", false], ["Copper reacts with acid but the product is insoluble", false]], "q": "Why does copper not react with dilute hydrochloric acid?", "wrong_explanations": {"1": "Density doesn't determine reactivity \u2014 gold is denser than magnesium but far less reactive.", "2": "HCl reacts with many metals \u2014 magnesium, zinc, iron all react vigorously with HCl. Only metals BELOW hydrogen in the series don't react.", "3": "Copper doesn't react with dilute HCl at all \u2014 it doesn't produce any product."}}]}, "summary": "Describe the reactivity series of metals and use it to predict reactions.", "theory": [{"content": "The REACTIVITY SERIES is a list of metals in order of their reactivity \u2014 from most reactive to least reactive.\n\nMost reactive (top) to least reactive (bottom):\nPotassium (K)\nSodium (Na)\nLithium (Li)\nCalcium (Ca)\nMagnesium (Mg)\nAluminium (Al)\nCarbon (C)* \u2014 not a metal, included as reference\nZinc (Zn)\nIron (Fe)\nTin (Sn)\nLead (Pb)\nHydrogen (H)* \u2014 not a metal, included as reference\nCopper (Cu)\nSilver (Ag)\nGold (Au)\nPlatinum (Pt)\n\nMemory aid: Potassium Sodium Lithium Calcium Magnesium Aluminium Carbon Zinc Iron Tin Lead Hydrogen Copper Silver Gold Platinum\n\u2192 'Please Stop Letting Clumsy Miners Accidentally Cut Zinc Into Tiny Little Holes \u2014 Copper Stands Guarding Platinum'", "heading": "The Reactivity Series"}, {"content": "The reactivity series is established by observing how vigorously metals react:\n\nREACTIONS WITH WATER:\nPotassium: explosive, ignites hydrogen gas (lilac flame).\nSodium: vigorous fizzing, melts into a ball, may ignite.\nLithium: steady fizzing.\nCalcium: steady bubbling, solution turns cloudy (Ca(OH)\u2082).\nMagnesium: barely reacts with cold water; reacts well with steam.\nIron: reacts very slowly with steam to form iron oxide and hydrogen.\nCopper, silver, gold: no reaction with water.\n\nREACTIONS WITH DILUTE ACID:\nMore reactive metals react faster and more vigorously with dilute acids.\nMagnesium: vigorous fizzing \u2014 reacts quickly.\nZinc: steady bubbling.\nIron: slow bubbling.\nCopper: no reaction \u2014 below hydrogen in reactivity series.\nGold, platinum: no reaction with dilute acid.", "heading": "Metal Reactions \u2014 Evidence for Reactivity Order"}, {"content": "A MORE REACTIVE metal will DISPLACE a LESS REACTIVE metal from its compound (salt or oxide).\n\nDISPLACEMENT FROM SALT SOLUTIONS:\nIf iron is added to copper sulfate solution:\nFe + CuSO\u2084 \u2192 FeSO\u2084 + Cu\nIron is more reactive than copper \u2192 iron displaces copper.\nObservation: blue solution turns pale green; copper metal deposits on the iron.\n\nIf copper is added to iron sulfate solution:\nNo reaction \u2014 copper is LESS reactive than iron.\n\nDISPLACEMENT FROM METAL OXIDES:\nHydrogen can displace metals BELOW it in the series from their oxides.\nCarbon can reduce (displace) metals below it in the series.\nCopper oxide + hydrogen:\nCuO + H\u2082 \u2192 Cu + H\u2082O (copper extracted from its oxide)\n\nMETAL OXIDES:\nMetal oxides are BASIC \u2014 they neutralise acids.\nThe more reactive the metal, the more stable its oxide \u2014 harder to decompose or reduce.", "heading": "Metal Oxides and Displacement Reactions"}]};
window.KS4SRC["energy-resources"] = {"common_mistake": "Bio-fuels ARE renewable \u2014 the plants regrow. Nuclear is NOT renewable \u2014 uranium is finite. Hydroelectric, wind, tidal and wave are all renewable. Also: 'renewable' does NOT mean 'zero environmental impact' \u2014 every resource has some impact.", "key_note": "Non-renewable: fossil fuels + nuclear. Renewable: wind, solar, hydro, bio-fuel, geothermal, tidal, wave. Most generation: turbine + generator (except solar PV). Fossil fuels: reliable, high energy density, but CO\u2082 + pollution. Renewables: lower impact but often intermittent. Nuclear: no CO\u2082 but radioactive waste.", "matching": {"instruction": "Match each resource to its type and main concern.", "pairs": [["Non-renewable", "Coal \u2014 CO\u2082 and SO\u2082 when burned; finite supply"], ["Non-renewable", "Nuclear \u2014 radioactive waste; uranium is finite"], ["Renewable", "Wind \u2014 no CO\u2082 during operation; intermittent; noise and visual impact"], ["Renewable", "Hydroelectric \u2014 no CO\u2082; reliable; dam flooding destroys habitats"], ["Renewable", "Bio-fuel \u2014 roughly carbon neutral; land use competes with food crops"]], "title": "Energy Resource \u2014 Type and Impact"}, "quiz": {"CF": [{"opts": [["Geothermal \u2014 heat from inside the Earth is continuously produced and will not run out on human timescales", true], ["Nuclear \u2014 uranium can be recycled so supplies will not run out", false], ["Coal \u2014 new coal forms continuously from organic material", false], ["Natural gas \u2014 underground reserves are replenished by geological processes", false]], "q": "Which of the following energy resources is renewable?", "wrong_explanations": {"1": "Nuclear fuel is FINITE \u2014 while some can be reprocessed, uranium supplies will eventually run out. It is non-renewable.", "2": "Coal takes MILLIONS of years to form \u2014 it is not replenished on any human-relevant timescale. Non-renewable.", "3": "Natural gas reserves are being used far faster than they form \u2014 a finite, non-renewable resource."}}, {"opts": [["They only generate electricity when the sun shines or wind blows \u2014 output is variable and cannot be guaranteed on demand", true], ["They are expensive to maintain and break down frequently", false], ["They produce too much electricity at peak times, requiring regular shutdown", false], ["They can only be used in specific countries, not globally", false]], "q": "Why are solar and wind described as 'intermittent' energy sources?", "wrong_explanations": {"1": "'Intermittent' refers specifically to VARIABLE, WEATHER-DEPENDENT output \u2014 not maintenance reliability.", "2": "Overproduction is a grid-management challenge but 'intermittent' specifically means UNPREDICTABLE output dependent on weather, not overproduction.", "3": "Wind and solar are used globally \u2014 'intermittent' describes the time-variability of output, not geographic limitation."}}], "CH": [{"opts": [["Geothermal \u2014 heat from inside the Earth is continuously produced and will not run out on human timescales", true], ["Nuclear \u2014 uranium can be recycled so supplies will not run out", false], ["Coal \u2014 new coal forms continuously from organic material", false], ["Natural gas \u2014 underground reserves are replenished by geological processes", false]], "q": "Which of the following energy resources is renewable?", "wrong_explanations": {"1": "Nuclear fuel is FINITE \u2014 while some can be reprocessed, uranium supplies will eventually run out. It is non-renewable.", "2": "Coal takes MILLIONS of years to form \u2014 it is not replenished on any human-relevant timescale. Non-renewable.", "3": "Natural gas reserves are being used far faster than they form \u2014 a finite, non-renewable resource."}}, {"opts": [["They only generate electricity when the sun shines or wind blows \u2014 output is variable and cannot be guaranteed on demand", true], ["They are expensive to maintain and break down frequently", false], ["They produce too much electricity at peak times, requiring regular shutdown", false], ["They can only be used in specific countries, not globally", false]], "q": "Why are solar and wind described as 'intermittent' energy sources?", "wrong_explanations": {"1": "'Intermittent' refers specifically to VARIABLE, WEATHER-DEPENDENT output \u2014 not maintenance reliability.", "2": "Overproduction is a grid-management challenge but 'intermittent' specifically means UNPREDICTABLE output dependent on weather, not overproduction.", "3": "Wind and solar are used globally \u2014 'intermittent' describes the time-variability of output, not geographic limitation."}}], "TF": [{"opts": [["Geothermal \u2014 heat from inside the Earth is continuously produced and will not run out on human timescales", true], ["Nuclear \u2014 uranium can be recycled so supplies will not run out", false], ["Coal \u2014 new coal forms continuously from organic material", false], ["Natural gas \u2014 underground reserves are replenished by geological processes", false]], "q": "Which of the following energy resources is renewable?", "wrong_explanations": {"1": "Nuclear fuel is FINITE \u2014 while some can be reprocessed, uranium supplies will eventually run out. It is non-renewable.", "2": "Coal takes MILLIONS of years to form \u2014 it is not replenished on any human-relevant timescale. Non-renewable.", "3": "Natural gas reserves are being used far faster than they form \u2014 a finite, non-renewable resource."}}, {"opts": [["They only generate electricity when the sun shines or wind blows \u2014 output is variable and cannot be guaranteed on demand", true], ["They are expensive to maintain and break down frequently", false], ["They produce too much electricity at peak times, requiring regular shutdown", false], ["They can only be used in specific countries, not globally", false]], "q": "Why are solar and wind described as 'intermittent' energy sources?", "wrong_explanations": {"1": "'Intermittent' refers specifically to VARIABLE, WEATHER-DEPENDENT output \u2014 not maintenance reliability.", "2": "Overproduction is a grid-management challenge but 'intermittent' specifically means UNPREDICTABLE output dependent on weather, not overproduction.", "3": "Wind and solar are used globally \u2014 'intermittent' describes the time-variability of output, not geographic limitation."}}], "TH": [{"opts": [["Geothermal \u2014 heat from inside the Earth is continuously produced and will not run out on human timescales", true], ["Nuclear \u2014 uranium can be recycled so supplies will not run out", false], ["Coal \u2014 new coal forms continuously from organic material", false], ["Natural gas \u2014 underground reserves are replenished by geological processes", false]], "q": "Which of the following energy resources is renewable?", "wrong_explanations": {"1": "Nuclear fuel is FINITE \u2014 while some can be reprocessed, uranium supplies will eventually run out. It is non-renewable.", "2": "Coal takes MILLIONS of years to form \u2014 it is not replenished on any human-relevant timescale. Non-renewable.", "3": "Natural gas reserves are being used far faster than they form \u2014 a finite, non-renewable resource."}}, {"opts": [["They only generate electricity when the sun shines or wind blows \u2014 output is variable and cannot be guaranteed on demand", true], ["They are expensive to maintain and break down frequently", false], ["They produce too much electricity at peak times, requiring regular shutdown", false], ["They can only be used in specific countries, not globally", false]], "q": "Why are solar and wind described as 'intermittent' energy sources?", "wrong_explanations": {"1": "'Intermittent' refers specifically to VARIABLE, WEATHER-DEPENDENT output \u2014 not maintenance reliability.", "2": "Overproduction is a grid-management challenge but 'intermittent' specifically means UNPREDICTABLE output dependent on weather, not overproduction.", "3": "Wind and solar are used globally \u2014 'intermittent' describes the time-variability of output, not geographic limitation."}}]}, "summary": "Compare renewable and non-renewable energy resources, their uses and environmental impacts.", "theory": [{"content": "NON-RENEWABLE energy resources WILL RUN OUT \u2014 cannot be replenished on human timescales.\nFOSSIL FUELS: coal, oil, natural gas \u2014 formed from ancient organic material over millions of years.\nNUCLEAR FUEL: uranium and plutonium \u2014 finite supply.\n\nRENEWABLE energy resources are REPLENISHED naturally and will not run out.\nWIND \u2014 kinetic energy of moving air drives turbines.\nSOLAR (SUN) \u2014 photovoltaic cells convert light \u2192 electricity; solar thermal heats water.\nHYDROELECTRICITY \u2014 falling/flowing water drives turbines.\nBIO-FUEL \u2014 fuels grown from plants (wood, ethanol, biodiesel) \u2014 regrow so renewable.\nGEOTHERMAL \u2014 heat from inside the Earth \u2192 steam \u2192 turbines.\nTIDES \u2014 tidal flow drives turbines.\nWATER WAVES \u2014 wave energy converters.\n\nAll renewables (except geothermal, tidal and nuclear) ultimately trace back to the Sun.", "heading": "Renewable and Non-Renewable Resources"}, {"content": "ELECTRICITY GENERATION \u2014 most methods use TURBINES + GENERATORS:\nFuel (or wind/water) \u2192 turbine spins \u2192 generator produces electricity.\nExceptions: solar PV converts light directly to electricity (no turbine).\n\nHEATING:\nGas central heating, geothermal hot springs, solar thermal panels.\n\nTRANSPORT:\nPetrol/diesel (from crude oil) currently dominant.\nElectric vehicles (charged from grid), hydrogen fuel cells, bio-fuels.\n\nWHY FOSSIL FUELS STILL DOMINATE:\nReliable on demand \u2014 not weather-dependent.\nHigh energy density \u2014 large amount of energy per kg.\nExisting infrastructure in place.\nBut: finite supply and significant environmental impact are driving a transition.", "heading": "Uses of Energy Resources"}, {"content": "FOSSIL FUELS:\nCO\u2082 released \u2192 greenhouse effect \u2192 climate change. Major concern.\nSO\u2082 (from coal/oil) \u2192 acid rain.\nNitrogen oxides \u2192 smog, air pollution.\nOil spills \u2192 marine ecosystem damage.\n\nNUCLEAR:\nNo CO\u2082 during operation \u2014 low carbon.\nRADIOACTIVE WASTE: hazardous, must be stored safely for thousands of years.\nRisk of major accidents (rare but severe: Chernobyl, Fukushima).\n\nWIND: No CO\u2082. Noise, visual impact, risk to birds. Intermittent.\nSOLAR: No CO\u2082. Panel manufacture uses energy and materials. Intermittent.\nHYDROELECTRIC: No CO\u2082. Reliable. Dam flooding destroys habitats.\nGEOTHERMAL: Low CO\u2082. Limited to active volcanic regions.\nBIO-FUEL: Roughly carbon neutral (CO\u2082 released = CO\u2082 absorbed while growing). Land use competes with food production.\nTIDES/WAVES: No CO\u2082. Disrupts marine ecosystems. Expensive to build.\n\nKEY TRADE-OFFS:\nRenewables: lower environmental impact but INTERMITTENT (wind/solar) \u2014 need storage or backup.\nFossil fuels: RELIABLE and on-demand but CO\u2082 and pollution.\nThe energy mix must balance reliability, cost and environmental impact.", "heading": "Environmental Impact of Energy Resources"}]};
window.KS4SRC["structure-of-atom"] = {"common_mistake": "The nucleus contains protons AND neutrons \u2014 NOT electrons. Electrons orbit the nucleus in shells. The mass of an atom comes almost entirely from the nucleus (protons + neutrons) \u2014 electron mass is negligible.", "key_note": "Atom: nucleus (protons + neutrons) + electrons in shells. Proton: +1, mass 1. Neutron: 0, mass 1. Electron: \u22121, negligible mass. Protons = electrons in neutral atom. Nuclear radius \u2248 1/10,000 atomic radius \u2014 mostly empty space. Shells: 2, 8, 8...", "matching": {"instruction": "Match each particle to its charge, mass and location.", "pairs": [["Proton", "Charge +1, mass 1 amu, found in the nucleus"], ["Neutron", "Charge 0, mass 1 amu, found in the nucleus"], ["Electron", "Charge \u22121, negligible mass, found in shells around the nucleus"], ["Nucleus", "Contains protons and neutrons \u2014 radius ~1/10,000 of the atom \u2014 most of atom's mass"]], "title": "Subatomic Particles"}, "quiz": {"CF": [{"opts": [["In the nucleus \u2014 protons and neutrons make up almost all the atomic mass; electrons are negligible", true], ["In the electron shells \u2014 electrons are the most numerous particles", false], ["Evenly spread throughout the atom \u2014 mass is uniformly distributed", false], ["On the outer electron shell \u2014 outermost electrons carry most of the mass", false]], "q": "Where is most of the mass of an atom concentrated?", "wrong_explanations": {"1": "There are often as many electrons as protons, but each electron weighs ~1/1836 of a proton \u2014 their combined mass is negligible.", "2": "Mass is concentrated in the tiny nucleus \u2014 the rest of the atom is mostly empty space.", "3": "Outer electrons have even less mass than inner ones \u2014 all electron mass is negligible."}}, {"opts": [["8 \u2014 neutral atoms always have equal numbers of protons and electrons", true], ["16 \u2014 electrons come in pairs so there are twice as many", false], ["4 \u2014 only half the protons are balanced by electrons", false], ["0 \u2014 electrons are not part of the neutral atom", false]], "q": "A neutral atom has 8 protons. How many electrons does it have?", "wrong_explanations": {"1": "Electrons don't automatically pair \u2014 the number equals the number of protons for charge balance.", "2": "Only half the protons balanced would give the atom a net positive charge \u2014 neutral means equal numbers.", "3": "Electrons are an essential part of every atom \u2014 removing them creates a positive ion, not a neutral atom."}}], "CH": [{"opts": [["In the nucleus \u2014 protons and neutrons make up almost all the atomic mass; electrons are negligible", true], ["In the electron shells \u2014 electrons are the most numerous particles", false], ["Evenly spread throughout the atom \u2014 mass is uniformly distributed", false], ["On the outer electron shell \u2014 outermost electrons carry most of the mass", false]], "q": "Where is most of the mass of an atom concentrated?", "wrong_explanations": {"1": "There are often as many electrons as protons, but each electron weighs ~1/1836 of a proton \u2014 their combined mass is negligible.", "2": "Mass is concentrated in the tiny nucleus \u2014 the rest of the atom is mostly empty space.", "3": "Outer electrons have even less mass than inner ones \u2014 all electron mass is negligible."}}, {"opts": [["8 \u2014 neutral atoms always have equal numbers of protons and electrons", true], ["16 \u2014 electrons come in pairs so there are twice as many", false], ["4 \u2014 only half the protons are balanced by electrons", false], ["0 \u2014 electrons are not part of the neutral atom", false]], "q": "A neutral atom has 8 protons. How many electrons does it have?", "wrong_explanations": {"1": "Electrons don't automatically pair \u2014 the number equals the number of protons for charge balance.", "2": "Only half the protons balanced would give the atom a net positive charge \u2014 neutral means equal numbers.", "3": "Electrons are an essential part of every atom \u2014 removing them creates a positive ion, not a neutral atom."}}], "TF": [{"opts": [["In the nucleus \u2014 protons and neutrons make up almost all the atomic mass; electrons are negligible", true], ["In the electron shells \u2014 electrons are the most numerous particles", false], ["Evenly spread throughout the atom \u2014 mass is uniformly distributed", false], ["On the outer electron shell \u2014 outermost electrons carry most of the mass", false]], "q": "Where is most of the mass of an atom concentrated?", "wrong_explanations": {"1": "There are often as many electrons as protons, but each electron weighs ~1/1836 of a proton \u2014 their combined mass is negligible.", "2": "Mass is concentrated in the tiny nucleus \u2014 the rest of the atom is mostly empty space.", "3": "Outer electrons have even less mass than inner ones \u2014 all electron mass is negligible."}}, {"opts": [["8 \u2014 neutral atoms always have equal numbers of protons and electrons", true], ["16 \u2014 electrons come in pairs so there are twice as many", false], ["4 \u2014 only half the protons are balanced by electrons", false], ["0 \u2014 electrons are not part of the neutral atom", false]], "q": "A neutral atom has 8 protons. How many electrons does it have?", "wrong_explanations": {"1": "Electrons don't automatically pair \u2014 the number equals the number of protons for charge balance.", "2": "Only half the protons balanced would give the atom a net positive charge \u2014 neutral means equal numbers.", "3": "Electrons are an essential part of every atom \u2014 removing them creates a positive ion, not a neutral atom."}}], "TH": [{"opts": [["In the nucleus \u2014 protons and neutrons make up almost all the atomic mass; electrons are negligible", true], ["In the electron shells \u2014 electrons are the most numerous particles", false], ["Evenly spread throughout the atom \u2014 mass is uniformly distributed", false], ["On the outer electron shell \u2014 outermost electrons carry most of the mass", false]], "q": "Where is most of the mass of an atom concentrated?", "wrong_explanations": {"1": "There are often as many electrons as protons, but each electron weighs ~1/1836 of a proton \u2014 their combined mass is negligible.", "2": "Mass is concentrated in the tiny nucleus \u2014 the rest of the atom is mostly empty space.", "3": "Outer electrons have even less mass than inner ones \u2014 all electron mass is negligible."}}, {"opts": [["8 \u2014 neutral atoms always have equal numbers of protons and electrons", true], ["16 \u2014 electrons come in pairs so there are twice as many", false], ["4 \u2014 only half the protons are balanced by electrons", false], ["0 \u2014 electrons are not part of the neutral atom", false]], "q": "A neutral atom has 8 protons. How many electrons does it have?", "wrong_explanations": {"1": "Electrons don't automatically pair \u2014 the number equals the number of protons for charge balance.", "2": "Only half the protons balanced would give the atom a net positive charge \u2014 neutral means equal numbers.", "3": "Electrons are an essential part of every atom \u2014 removing them creates a positive ion, not a neutral atom."}}]}, "summary": "Describe the structure of an atom including the nucleus, protons, neutrons and electrons.", "theory": [{"content": "Atoms are extremely small \u2014 radius approximately 1 \u00d7 10\u207b\u00b9\u2070 m (0.1 nanometres).\n\nStructure:\nNUCLEUS at the centre \u2014 contains PROTONS and NEUTRONS.\nELECTRONS orbit the nucleus at different distances (energy levels/shells).\n\nThe nucleus is tiny compared to the whole atom:\nNuclear radius \u2248 1/10,000 of the atomic radius.\nMost of the atom is empty space.\n\nSIZE COMPARISON:\nAtomic radius: ~1 \u00d7 10\u207b\u00b9\u2070 m\nNuclear radius: ~1 \u00d7 10\u207b\u00b9\u2074 m\nIf the nucleus were the size of a football (30 cm), the atom would be ~3 km across.", "heading": "Inside the Atom"}, {"content": "Three subatomic particles:\n\nPROTON:\nMass: 1 atomic mass unit (amu)\nCharge: +1\nLocation: nucleus\n\nNEUTRON:\nMass: 1 amu\nCharge: 0 (neutral)\nLocation: nucleus\n\nELECTRON:\nMass: approximately 1/1836 amu (negligible)\nCharge: \u22121\nLocation: shells (energy levels) around the nucleus\n\nOVERALL CHARGE:\nNumber of protons = number of electrons in a neutral atom.\nPositive protons balanced by negative electrons \u2192 atom has no overall charge.\n\nMASS:\nAlmost all the mass is in the nucleus (protons + neutrons).\nElectron mass is negligible.", "heading": "Properties of Subatomic Particles"}, {"content": "Electrons occupy SHELLS (energy levels) at different distances from the nucleus.\n\nShells fill from the innermost outwards:\nShell 1 (closest to nucleus): maximum 2 electrons\nShell 2: maximum 8 electrons\nShell 3: maximum 8 electrons (for elements 1\u201320)\n\nEXAMPLES:\nHydrogen (1 proton, 1 electron): 1 shell \u2014 1 electron in shell 1\nCarbon (6 protons, 6 electrons): 2 shells \u2014 2 in shell 1, 4 in shell 2\nSodium (11 protons, 11 electrons): 3 shells \u2014 2, 8, 1\n\nELECTRONS AND CHEMISTRY:\nThe arrangement of electrons determines an element's chemical properties.\nOuter shell electrons are involved in chemical bonding.\nElements in the same group of the periodic table have the same number of outer shell electrons.\n\nWhen an electron ABSORBS energy it moves to a higher shell (further from nucleus).\nWhen it releases energy it moves to a lower shell \u2014 emitting radiation (light or other EM waves).", "heading": "Electron Shells and Energy Levels"}]};
window.KS4SRC["plant-tissues"] = {"common_mistake": "Xylem transports WATER and MINERALS. Phloem transports SUGARS. Students regularly mix these up. A good memory trick: Xylem = water (X for H2O is a stretch, but think: Xylem goes up like water). Phloem = food (sugars). Also: xylem cells are DEAD; phloem cells are LIVING.", "higher": "The transpiration stream is driven by evaporation from leaves \u2014 creating a tension that pulls water continuously up through xylem (cohesion-tension theory). Students should be able to explain how the transpiration rate is measured using a potometer. Phloem translocation is driven by active loading of sucrose at source cells (using ATP from companion cells) creating a pressure gradient to sink cells.", "key_note": "Xylem: water + minerals, upwards only, dead cells, lignified walls. Phloem: sugars (translocation), both directions, living cells. Stomata: CO\u2082 in, O\u2082 and water vapour out. Controlled by guard cells.", "matching": {"instruction": "Match each tissue to its role in the plant.", "pairs": [["Xylem", "Transports water and mineral ions from roots to leaves \u2014 dead, hollow, lignified"], ["Phloem", "Transports dissolved sugars from leaves to the rest of the plant \u2014 translocation"], ["Palisade mesophyll", "Packed with chloroplasts near leaf surface \u2014 main site of photosynthesis"], ["Spongy mesophyll", "Air spaces between cells \u2014 allows CO\u2082 and O\u2082 to diffuse easily"], ["Guard cells", "Control opening and closing of stomata \u2014 regulate gas exchange and water loss"], ["Waxy cuticle", "Waterproof covering on epidermis \u2014 reduces water loss from the leaf"]], "title": "Match the Plant Tissue to its Function"}, "quiz": {"CF": [{"opts": [["Water and dissolved mineral ions \u2014 upwards from roots to leaves", true], ["Dissolved sugars from leaves to other parts of the plant", false], ["Oxygen produced by photosynthesis", false], ["Carbon dioxide for use in photosynthesis", false]], "q": "What is transported in xylem?", "wrong_explanations": {"1": "Dissolved sugars = PHLOEM (translocation). Xylem carries water and minerals only.", "2": "Oxygen diffuses through air spaces in the spongy mesophyll and out through stomata \u2014 it doesn't travel in xylem.", "3": "CO\u2082 diffuses through stomata into air spaces \u2014 it doesn't travel in xylem."}}, {"opts": [["Dead cells have no contents \u2014 forming a completely hollow tube for water to flow through without obstruction", true], ["Xylem cells die because the lignin in their walls is toxic", false], ["Dead cells are lighter, helping water move upwards against gravity", false], ["Xylem cells die when the plant is no longer growing", false]], "q": "Why are xylem cells dead?", "wrong_explanations": {"1": "Lignin is not toxic \u2014 it strengthens the walls. The cells die as part of their normal development, leaving behind a hollow lignified tube.", "2": "Dead cell content doesn't significantly change the weight of xylem \u2014 water moves upward due to the transpiration pull, not because of weight.", "3": "Xylem cells die as they mature during normal development, regardless of whether the plant is actively growing \u2014 this is a programmed developmental process."}}, {"opts": [["Allow CO\u2082 in for photosynthesis and O\u2082 out \u2014 also allow water vapour to escape during transpiration", true], ["Absorb water directly from the air into the leaf", false], ["Produce the waxy cuticle to reduce water loss", false], ["Store glucose produced by photosynthesis", false]], "q": "What is the role of stomata in leaves?", "wrong_explanations": {"1": "Stomata can absorb some water vapour in humid conditions, but their primary function is gas EXCHANGE, not water absorption.", "2": "The waxy cuticle is produced by the EPIDERMIS cells \u2014 it is a secreted layer, not produced by stomata.", "3": "Glucose storage as starch happens in chloroplasts and other cells \u2014 stomata are pores for gas exchange."}}], "CH": [{"opts": [["Water and dissolved mineral ions \u2014 upwards from roots to leaves", true], ["Dissolved sugars from leaves to other parts of the plant", false], ["Oxygen produced by photosynthesis", false], ["Carbon dioxide for use in photosynthesis", false]], "q": "What is transported in xylem?", "wrong_explanations": {"1": "Dissolved sugars = PHLOEM (translocation). Xylem carries water and minerals only.", "2": "Oxygen diffuses through air spaces in the spongy mesophyll and out through stomata \u2014 it doesn't travel in xylem.", "3": "CO\u2082 diffuses through stomata into air spaces \u2014 it doesn't travel in xylem."}}, {"opts": [["Dead cells have no contents \u2014 forming a completely hollow tube for water to flow through without obstruction", true], ["Xylem cells die because the lignin in their walls is toxic", false], ["Dead cells are lighter, helping water move upwards against gravity", false], ["Xylem cells die when the plant is no longer growing", false]], "q": "Why are xylem cells dead?", "wrong_explanations": {"1": "Lignin is not toxic \u2014 it strengthens the walls. The cells die as part of their normal development, leaving behind a hollow lignified tube.", "2": "Dead cell content doesn't significantly change the weight of xylem \u2014 water moves upward due to the transpiration pull, not because of weight.", "3": "Xylem cells die as they mature during normal development, regardless of whether the plant is actively growing \u2014 this is a programmed developmental process."}}, {"opts": [["Allow CO\u2082 in for photosynthesis and O\u2082 out \u2014 also allow water vapour to escape during transpiration", true], ["Absorb water directly from the air into the leaf", false], ["Produce the waxy cuticle to reduce water loss", false], ["Store glucose produced by photosynthesis", false]], "q": "What is the role of stomata in leaves?", "wrong_explanations": {"1": "Stomata can absorb some water vapour in humid conditions, but their primary function is gas EXCHANGE, not water absorption.", "2": "The waxy cuticle is produced by the EPIDERMIS cells \u2014 it is a secreted layer, not produced by stomata.", "3": "Glucose storage as starch happens in chloroplasts and other cells \u2014 stomata are pores for gas exchange."}}], "TF": [{"opts": [["Water and dissolved mineral ions \u2014 upwards from roots to leaves", true], ["Dissolved sugars from leaves to other parts of the plant", false], ["Oxygen produced by photosynthesis", false], ["Carbon dioxide for use in photosynthesis", false]], "q": "What is transported in xylem?", "wrong_explanations": {"1": "Dissolved sugars = PHLOEM (translocation). Xylem carries water and minerals only.", "2": "Oxygen diffuses through air spaces in the spongy mesophyll and out through stomata \u2014 it doesn't travel in xylem.", "3": "CO\u2082 diffuses through stomata into air spaces \u2014 it doesn't travel in xylem."}}, {"opts": [["Dead cells have no contents \u2014 forming a completely hollow tube for water to flow through without obstruction", true], ["Xylem cells die because the lignin in their walls is toxic", false], ["Dead cells are lighter, helping water move upwards against gravity", false], ["Xylem cells die when the plant is no longer growing", false]], "q": "Why are xylem cells dead?", "wrong_explanations": {"1": "Lignin is not toxic \u2014 it strengthens the walls. The cells die as part of their normal development, leaving behind a hollow lignified tube.", "2": "Dead cell content doesn't significantly change the weight of xylem \u2014 water moves upward due to the transpiration pull, not because of weight.", "3": "Xylem cells die as they mature during normal development, regardless of whether the plant is actively growing \u2014 this is a programmed developmental process."}}, {"opts": [["Allow CO\u2082 in for photosynthesis and O\u2082 out \u2014 also allow water vapour to escape during transpiration", true], ["Absorb water directly from the air into the leaf", false], ["Produce the waxy cuticle to reduce water loss", false], ["Store glucose produced by photosynthesis", false]], "q": "What is the role of stomata in leaves?", "wrong_explanations": {"1": "Stomata can absorb some water vapour in humid conditions, but their primary function is gas EXCHANGE, not water absorption.", "2": "The waxy cuticle is produced by the EPIDERMIS cells \u2014 it is a secreted layer, not produced by stomata.", "3": "Glucose storage as starch happens in chloroplasts and other cells \u2014 stomata are pores for gas exchange."}}], "TH": [{"opts": [["Water and dissolved mineral ions \u2014 upwards from roots to leaves", true], ["Dissolved sugars from leaves to other parts of the plant", false], ["Oxygen produced by photosynthesis", false], ["Carbon dioxide for use in photosynthesis", false]], "q": "What is transported in xylem?", "wrong_explanations": {"1": "Dissolved sugars = PHLOEM (translocation). Xylem carries water and minerals only.", "2": "Oxygen diffuses through air spaces in the spongy mesophyll and out through stomata \u2014 it doesn't travel in xylem.", "3": "CO\u2082 diffuses through stomata into air spaces \u2014 it doesn't travel in xylem."}}, {"opts": [["Dead cells have no contents \u2014 forming a completely hollow tube for water to flow through without obstruction", true], ["Xylem cells die because the lignin in their walls is toxic", false], ["Dead cells are lighter, helping water move upwards against gravity", false], ["Xylem cells die when the plant is no longer growing", false]], "q": "Why are xylem cells dead?", "wrong_explanations": {"1": "Lignin is not toxic \u2014 it strengthens the walls. The cells die as part of their normal development, leaving behind a hollow lignified tube.", "2": "Dead cell content doesn't significantly change the weight of xylem \u2014 water moves upward due to the transpiration pull, not because of weight.", "3": "Xylem cells die as they mature during normal development, regardless of whether the plant is actively growing \u2014 this is a programmed developmental process."}}, {"opts": [["Allow CO\u2082 in for photosynthesis and O\u2082 out \u2014 also allow water vapour to escape during transpiration", true], ["Absorb water directly from the air into the leaf", false], ["Produce the waxy cuticle to reduce water loss", false], ["Store glucose produced by photosynthesis", false]], "q": "What is the role of stomata in leaves?", "wrong_explanations": {"1": "Stomata can absorb some water vapour in humid conditions, but their primary function is gas EXCHANGE, not water absorption.", "2": "The waxy cuticle is produced by the EPIDERMIS cells \u2014 it is a secreted layer, not produced by stomata.", "3": "Glucose storage as starch happens in chloroplasts and other cells \u2014 stomata are pores for gas exchange."}}]}, "summary": "Describe the tissues found in plant organs and how they are adapted to their functions.", "theory": [{"content": "Plants are multicellular organisms with specialised organs, just like animals.\n\nThe main plant organs are:\nLEAF \u2014 the main site of photosynthesis and gas exchange.\nSTEM \u2014 provides support and transports substances between roots and leaves.\nROOT \u2014 anchors the plant and absorbs water and mineral ions from the soil.\nFLOWER \u2014 involved in reproduction.\n\nEach organ is made of different types of TISSUE, each adapted to its specific function.", "heading": "Plant Organs"}, {"content": "The leaf is the most important organ for photosynthesis. It contains several specialised tissues:\n\nEPIDERMIS (upper and lower):\nA thin, transparent layer covering the leaf surface.\nProduces a WAXY CUTICLE \u2014 a waterproof coating that reduces water loss by evaporation.\n\nPALISADE MESOPHYLL:\nFound in the upper part of the leaf \u2014 closest to sunlight.\nCells are tall and column-shaped, packed with many CHLOROPLASTS.\nThis is the main site of photosynthesis \u2014 receives maximum light.\n\nSPONGY MESOPHYLL:\nBelow the palisade layer.\nCells are loosely arranged with large AIR SPACES between them.\nAir spaces allow CO\u2082 to diffuse easily to photosynthesising cells.\nAlso allows O\u2082 produced by photosynthesis to diffuse out.\n\nGUARD CELLS and STOMATA:\nGuard cells are pairs of cells surrounding tiny pores called STOMATA (singular: stoma) on the lower leaf surface.\nStomata open to allow CO\u2082 in for photosynthesis and O\u2082 out \u2014 also allow water vapour to escape (transpiration).\nGuard cells control stomata opening: in the light, guard cells absorb water and become turgid \u2192 stomata OPEN. In the dark or when dehydrated, guard cells lose water \u2192 stomata CLOSE.\n\nXYLEM and PHLOEM:\nRun through the leaf as vascular bundles (veins).\nXylem brings water to the leaf. Phloem takes away sugars made by photosynthesis.", "heading": "Tissues in the Leaf"}, {"content": "Xylem is a tissue that transports WATER and dissolved MINERAL IONS from the roots upwards to the leaves.\n\nKey features of xylem cells:\nDEAD cells \u2014 no cytoplasm or nucleus, forming a completely hollow tube.\nNo end walls \u2014 cells are stacked end-to-end to form one continuous open column.\nWalls strengthened with LIGNIN \u2014 a hard, waterproof material that makes xylem very strong and prevents the tubes from collapsing.\nWater moves through xylem in one direction only \u2014 upwards.\n\nThe movement of water through xylem is driven by the TRANSPIRATION STREAM \u2014 water evaporating from leaves creates a pulling force that draws water up from the roots.", "heading": "Xylem Tissue"}, {"content": "Phloem is a tissue that transports dissolved SUGARS (mainly sucrose) from leaves to other parts of the plant. This process is called TRANSLOCATION.\n\nKey features of phloem cells:\nLIVING cells \u2014 unlike xylem, phloem cells are alive.\nSIEVE TUBES \u2014 cells with perforated end walls (sieve plates) that allow sugar solution to flow through.\nCOMPANION CELLS \u2014 next to each sieve tube cell, providing energy (ATP) for the active loading of sugars into the phloem.\n\nSugars travel in BOTH DIRECTIONS in phloem \u2014 from leaves (source) to roots, growing tips, fruits and other areas where sugar is needed (sinks).", "heading": "Phloem Tissue"}]};
window.KS4SRC["waste-management"] = {"common_mistake": "Pollution is not only about litter you can see. Invisible pollution \u2014 sewage and fertiliser in water, acidic gases in air, pesticides soaking into land \u2014 often does the most damage to biodiversity. Also remember: MORE people AND a higher standard of living both increase waste, not just population size alone.", "key_note": "Rising population + higher living standards \u2192 more resources used, more waste, more pollution. Pollution occurs in water (sewage, fertiliser, toxic chemicals), air (smoke, sulfur dioxide/acid rain) and land (landfill, pesticides/herbicides). Pollution kills organisms and reduces biodiversity.", "matching": {"instruction": "Sort each pollutant into the environment it mainly pollutes.", "pairs": [["Water", "Sewage \u2014 untreated human waste released into rivers and seas"], ["Water", "Fertiliser washed off farmland causing eutrophication"], ["Air", "Sulfur dioxide from burning fuels, causing acid rain"], ["Air", "Smoke and smoke particles from combustion"], ["Land", "Landfill \u2014 rubbish buried in the ground"], ["Land", "Pesticides and herbicides sprayed on crops"]], "title": "Where Does This Pollution Happen?"}, "quiz": {"CF": [{"opts": [["People use more resources and produce more waste per person", true], ["People automatically have more children", false], ["A higher standard of living has no effect on pollution", false], ["People move to the countryside where there is less waste", false]], "q": "Why does a rising human standard of living increase pollution, even where population is stable?", "wrong_explanations": {"1": "Standard of living is about resource use per person, not birth rate \u2014 both population size AND resource use per person raise pollution.", "2": "It is the extra resource use and waste per person that increases pollution, not the standard of living itself being harmless.", "3": "Where people go does not remove the waste \u2014 a higher standard of living means each person consumes and discards more."}}, {"opts": [["Water", true], ["Air", false], ["Land only", false], ["None \u2014 fertiliser is not a pollutant", false]], "q": "Fertiliser washing into a river reduces biodiversity. Which environment is being polluted?", "wrong_explanations": {"1": "Fertiliser in a river is water pollution \u2014 it causes eutrophication, lowering oxygen and killing fish.", "2": "Fertiliser run-off enters water, not the air.", "3": "Fertiliser is a pollutant when it reaches water \u2014 it damages the ecosystem even though it helps crops grow on land."}}], "CH": [{"opts": [["People use more resources and produce more waste per person", true], ["People automatically have more children", false], ["A higher standard of living has no effect on pollution", false], ["People move to the countryside where there is less waste", false]], "q": "Why does a rising human standard of living increase pollution, even where population is stable?", "wrong_explanations": {"1": "Standard of living is about resource use per person, not birth rate \u2014 both population size AND resource use per person raise pollution.", "2": "It is the extra resource use and waste per person that increases pollution, not the standard of living itself being harmless.", "3": "Where people go does not remove the waste \u2014 a higher standard of living means each person consumes and discards more."}}, {"opts": [["Water", true], ["Air", false], ["Land only", false], ["None \u2014 fertiliser is not a pollutant", false]], "q": "Fertiliser washing into a river reduces biodiversity. Which environment is being polluted?", "wrong_explanations": {"1": "Fertiliser in a river is water pollution \u2014 it causes eutrophication, lowering oxygen and killing fish.", "2": "Fertiliser run-off enters water, not the air.", "3": "Fertiliser is a pollutant when it reaches water \u2014 it damages the ecosystem even though it helps crops grow on land."}}], "TF": [{"opts": [["People use more resources and produce more waste per person", true], ["People automatically have more children", false], ["A higher standard of living has no effect on pollution", false], ["People move to the countryside where there is less waste", false]], "q": "Why does a rising human standard of living increase pollution, even where population is stable?", "wrong_explanations": {"1": "Standard of living is about resource use per person, not birth rate \u2014 both population size AND resource use per person raise pollution.", "2": "It is the extra resource use and waste per person that increases pollution, not the standard of living itself being harmless.", "3": "Where people go does not remove the waste \u2014 a higher standard of living means each person consumes and discards more."}}, {"opts": [["Water", true], ["Air", false], ["Land only", false], ["None \u2014 fertiliser is not a pollutant", false]], "q": "Fertiliser washing into a river reduces biodiversity. Which environment is being polluted?", "wrong_explanations": {"1": "Fertiliser in a river is water pollution \u2014 it causes eutrophication, lowering oxygen and killing fish.", "2": "Fertiliser run-off enters water, not the air.", "3": "Fertiliser is a pollutant when it reaches water \u2014 it damages the ecosystem even though it helps crops grow on land."}}], "TH": [{"opts": [["People use more resources and produce more waste per person", true], ["People automatically have more children", false], ["A higher standard of living has no effect on pollution", false], ["People move to the countryside where there is less waste", false]], "q": "Why does a rising human standard of living increase pollution, even where population is stable?", "wrong_explanations": {"1": "Standard of living is about resource use per person, not birth rate \u2014 both population size AND resource use per person raise pollution.", "2": "It is the extra resource use and waste per person that increases pollution, not the standard of living itself being harmless.", "3": "Where people go does not remove the waste \u2014 a higher standard of living means each person consumes and discards more."}}, {"opts": [["Water", true], ["Air", false], ["Land only", false], ["None \u2014 fertiliser is not a pollutant", false]], "q": "Fertiliser washing into a river reduces biodiversity. Which environment is being polluted?", "wrong_explanations": {"1": "Fertiliser in a river is water pollution \u2014 it causes eutrophication, lowering oxygen and killing fish.", "2": "Fertiliser run-off enters water, not the air.", "3": "Fertiliser is a pollutant when it reaches water \u2014 it damages the ecosystem even though it helps crops grow on land."}}]}, "summary": "Explain how human population growth and rising living standards increase pollution of water, air and land, reducing biodiversity.", "theory": [{"content": "The human POPULATION is growing rapidly, and the STANDARD OF LIVING is rising in many countries.\n\nBoth of these mean humans use MORE RESOURCES and produce MORE WASTE.\n\nUnless this waste and the chemicals in it are handled properly, more POLLUTION is caused.\n\nPollution KILLS plants and animals, which REDUCES BIODIVERSITY (the variety of living things in an area).", "heading": "Why pollution is increasing"}, {"content": "Pollution can occur in three places:\n\nIN WATER \u2014 from sewage, from fertiliser washed off fields, and from toxic chemicals. Fertiliser causes eutrophication (algae bloom \u2192 less oxygen \u2192 fish die).\n\nIN AIR \u2014 from smoke and from acidic gases such as sulfur dioxide, which cause acid rain.\n\nON LAND \u2014 from landfill (buried rubbish) and from toxic chemicals such as pesticides and herbicides, which can wash into soil and water.", "heading": "The three places pollution happens"}, {"content": "Every source of pollution damages HABITATS and directly KILLS organisms.\n\nWhen organisms die or habitats are destroyed, the number of species and their numbers fall \u2014 biodiversity DECREASES.\n\nManaging waste properly (treating sewage, filtering gases, recycling) reduces pollution and helps protect biodiversity.", "heading": "Why it matters"}]};
window.KS4SRC["earths-resources"] = {"common_mistake": "Sustainable development does NOT mean stopping all industrial activity \u2014 it means developing in ways that preserve resources and environments for future generations. It balances economic, environmental and social needs \u2014 not just environmental protection alone.", "higher": "Calculate atom economy for industrial reactions. Evaluate green chemistry principles. Phytomining and bioleaching as sustainable alternatives for low-grade ores. Compare traditional and alternative methods across economic, environmental and practical dimensions.", "key_note": "Earth's resources: minerals, fossil fuels, water, biological materials. Non-renewable: finite, cannot be replaced quickly. Sustainable development: meet present needs without preventing future generations from meeting theirs. Green chemistry: minimise waste, use renewable feedstocks, reduce energy. Recycling and atom economy are key.", "matching": {"instruction": "Sort each practice into sustainable or unsustainable.", "pairs": [["Sustainable", "Recycling aluminium \u2014 uses 95% less energy than extracting from ore"], ["Unsustainable", "Burning fossil fuels at current rates \u2014 non-renewable, finite supply"], ["Sustainable", "Using bioplastics from plant materials \u2014 renewable feedstock"], ["Unsustainable", "Deforestation for agriculture \u2014 removes carbon sinks faster than they regrow"], ["Sustainable", "Designing reactions with high atom economy \u2014 less waste produced"]], "title": "Sustainable or Not Sustainable?"}, "quiz": {"CF": [{"opts": [["Meeting present needs without preventing future generations from meeting their own needs \u2014 balancing economic, environmental and social factors", true], ["Stopping all chemical manufacturing to protect the environment", false], ["Using only natural chemicals \u2014 avoiding synthetic compounds", false], ["Developing countries should not industrialise \u2014 only developed nations can use resources", false]], "q": "What does 'sustainable development' mean in chemistry?", "wrong_explanations": {"1": "Sustainable development explicitly does NOT mean stopping industrial activity \u2014 it means developing more responsibly.", "2": "Synthetic chemicals can be part of sustainable development if produced using renewable resources and efficient processes.", "3": "Sustainable development specifically requires EQUITY \u2014 all nations have the right to develop, but in sustainable ways."}}, {"opts": [["Recycling uses about 95% less electrical energy than electrolysis of molten aluminium oxide", true], ["Bauxite is not a natural resource \u2014 it is produced artificially", false], ["Recycled aluminium is stronger than freshly extracted aluminium", false], ["There is no bauxite left \u2014 all aluminium must now be recycled", false]], "q": "Why is recycling aluminium more sustainable than extracting new aluminium from bauxite ore?", "wrong_explanations": {"1": "Bauxite (aluminium ore) is a natural mineral found in the Earth's crust \u2014 it is a natural resource.", "2": "Recycled and fresh aluminium have the same properties \u2014 sustainability is about energy and resource use, not material strength.", "3": "Bauxite reserves still exist \u2014 but they are finite, and extraction is energy-intensive. The key advantage of recycling is energy saving."}}], "CH": [{"opts": [["Meeting present needs without preventing future generations from meeting their own needs \u2014 balancing economic, environmental and social factors", true], ["Stopping all chemical manufacturing to protect the environment", false], ["Using only natural chemicals \u2014 avoiding synthetic compounds", false], ["Developing countries should not industrialise \u2014 only developed nations can use resources", false]], "q": "What does 'sustainable development' mean in chemistry?", "wrong_explanations": {"1": "Sustainable development explicitly does NOT mean stopping industrial activity \u2014 it means developing more responsibly.", "2": "Synthetic chemicals can be part of sustainable development if produced using renewable resources and efficient processes.", "3": "Sustainable development specifically requires EQUITY \u2014 all nations have the right to develop, but in sustainable ways."}}, {"opts": [["Recycling uses about 95% less electrical energy than electrolysis of molten aluminium oxide", true], ["Bauxite is not a natural resource \u2014 it is produced artificially", false], ["Recycled aluminium is stronger than freshly extracted aluminium", false], ["There is no bauxite left \u2014 all aluminium must now be recycled", false]], "q": "Why is recycling aluminium more sustainable than extracting new aluminium from bauxite ore?", "wrong_explanations": {"1": "Bauxite (aluminium ore) is a natural mineral found in the Earth's crust \u2014 it is a natural resource.", "2": "Recycled and fresh aluminium have the same properties \u2014 sustainability is about energy and resource use, not material strength.", "3": "Bauxite reserves still exist \u2014 but they are finite, and extraction is energy-intensive. The key advantage of recycling is energy saving."}}], "TF": [{"opts": [["Meeting present needs without preventing future generations from meeting their own needs \u2014 balancing economic, environmental and social factors", true], ["Stopping all chemical manufacturing to protect the environment", false], ["Using only natural chemicals \u2014 avoiding synthetic compounds", false], ["Developing countries should not industrialise \u2014 only developed nations can use resources", false]], "q": "What does 'sustainable development' mean in chemistry?", "wrong_explanations": {"1": "Sustainable development explicitly does NOT mean stopping industrial activity \u2014 it means developing more responsibly.", "2": "Synthetic chemicals can be part of sustainable development if produced using renewable resources and efficient processes.", "3": "Sustainable development specifically requires EQUITY \u2014 all nations have the right to develop, but in sustainable ways."}}, {"opts": [["Recycling uses about 95% less electrical energy than electrolysis of molten aluminium oxide", true], ["Bauxite is not a natural resource \u2014 it is produced artificially", false], ["Recycled aluminium is stronger than freshly extracted aluminium", false], ["There is no bauxite left \u2014 all aluminium must now be recycled", false]], "q": "Why is recycling aluminium more sustainable than extracting new aluminium from bauxite ore?", "wrong_explanations": {"1": "Bauxite (aluminium ore) is a natural mineral found in the Earth's crust \u2014 it is a natural resource.", "2": "Recycled and fresh aluminium have the same properties \u2014 sustainability is about energy and resource use, not material strength.", "3": "Bauxite reserves still exist \u2014 but they are finite, and extraction is energy-intensive. The key advantage of recycling is energy saving."}}], "TH": [{"opts": [["Meeting present needs without preventing future generations from meeting their own needs \u2014 balancing economic, environmental and social factors", true], ["Stopping all chemical manufacturing to protect the environment", false], ["Using only natural chemicals \u2014 avoiding synthetic compounds", false], ["Developing countries should not industrialise \u2014 only developed nations can use resources", false]], "q": "What does 'sustainable development' mean in chemistry?", "wrong_explanations": {"1": "Sustainable development explicitly does NOT mean stopping industrial activity \u2014 it means developing more responsibly.", "2": "Synthetic chemicals can be part of sustainable development if produced using renewable resources and efficient processes.", "3": "Sustainable development specifically requires EQUITY \u2014 all nations have the right to develop, but in sustainable ways."}}, {"opts": [["Recycling uses about 95% less electrical energy than electrolysis of molten aluminium oxide", true], ["Bauxite is not a natural resource \u2014 it is produced artificially", false], ["Recycled aluminium is stronger than freshly extracted aluminium", false], ["There is no bauxite left \u2014 all aluminium must now be recycled", false]], "q": "Why is recycling aluminium more sustainable than extracting new aluminium from bauxite ore?", "wrong_explanations": {"1": "Bauxite (aluminium ore) is a natural mineral found in the Earth's crust \u2014 it is a natural resource.", "2": "Recycled and fresh aluminium have the same properties \u2014 sustainability is about energy and resource use, not material strength.", "3": "Bauxite reserves still exist \u2014 but they are finite, and extraction is energy-intensive. The key advantage of recycling is energy saving."}}]}, "summary": "Describe how humans use the Earth's resources and the importance of sustainable development.", "theory": [{"content": "Humans use NATURAL RESOURCES from the Earth \u2014 materials and energy obtained from the natural environment.\n\nTypes of resources:\nMINERALS AND METALS \u2014 extracted from the Earth's crust (iron ore, aluminium ore, copper ore).\nFOSSIL FUELS \u2014 coal, oil, natural gas (non-renewable \u2014 takes millions of years to form).\nAIR \u2014 nitrogen and oxygen extracted from air.\nWATER \u2014 freshwater for drinking, industry, agriculture.\nBIOLOGICAL RESOURCES \u2014 timber, plants, animals.\n\nRENEWABLE vs NON-RENEWABLE:\nNon-renewable: fossil fuels, minerals, metals \u2014 finite, will run out. Formed over millions of years.\nRenewable: timber (regrows), some materials can be recycled, energy from sun/wind/water.\n\nMany resources are FINITE \u2014 once used, they cannot be replenished in human timescales.", "heading": "The Earth's Natural Resources"}, {"content": "SUSTAINABLE DEVELOPMENT means meeting the needs of the PRESENT without compromising the ability of FUTURE GENERATIONS to meet their own needs.\n\nThis requires balancing:\nECONOMIC GROWTH \u2014 industries and livelihoods.\nENVIRONMENTAL PROTECTION \u2014 not destroying ecosystems or depleting resources.\nSOCIAL EQUITY \u2014 ensuring all people benefit fairly.\n\nAPPLICATIONS IN CHEMISTRY:\nGREEN CHEMISTRY \u2014 designing chemical processes that minimise waste, use renewable resources and reduce energy consumption.\nATOM ECONOMY \u2014 designing reactions that convert as much of the reactants as possible into the desired product (less waste).\nUSING RENEWABLE FEEDSTOCKS \u2014 e.g. bioplastics from plant materials rather than petroleum.\nCARBON CAPTURE \u2014 storing CO\u2082 from fossil fuel burning to prevent atmospheric build-up.\n\nSUSTAINABLE USE OF METALS:\nRecycle metals rather than mining new ore.\nDevelop more efficient extraction processes.\nFind alternative materials.", "heading": "Sustainable Development"}, {"content": "The GROWING GLOBAL POPULATION means:\nMore food needed \u2192 more agricultural land, more fertilisers.\nMore energy needed \u2192 more fossil fuels burned (rising CO\u2082).\nMore materials needed \u2192 more mining, more deforestation.\nMore waste produced \u2192 more landfill, more pollution.\n\nKEY CONFLICTS:\nExtraction of metals: mining disrupts ecosystems, creates waste, uses energy.\nFossil fuels: vital energy source but non-renewable and cause climate change.\nAgriculture: feeds billions but uses vast land, water and chemicals.\n\nWhy chemistry is important for sustainability:\nChemists develop more efficient processes (less energy, less waste).\nCreate new materials to replace scarce ones.\nDevelop renewable energy technologies (solar cells, batteries, fuel cells).\nDevelop better pollution control.\nFind ways to recycle and reuse materials.", "heading": "Finite Resources and Human Impact"}]};
window.KS4SRC["development-atomic-model"] = {"common_mistake": "The alpha scattering experiment DISPROVED the plum pudding model \u2014 it did NOT confirm it. The fact that MOST particles passed straight through shows atoms are mostly empty space. The FEW that bounced back showed the nucleus is small and dense.", "key_note": "Solid sphere \u2192 plum pudding (Thomson, electrons discovered) \u2192 nuclear model (Rutherford, alpha scattering). Alpha scattering: most pass through (empty space), few bounce back (small dense positive nucleus). Bohr: electrons in fixed shells. Chadwick: neutron discovered 1932.", "matching": {"instruction": "Match each model or discovery to the evidence that led to it.", "pairs": [["Solid sphere model abandoned", "Discovery of the electron \u2014 atoms have internal structure, can be divided"], ["Plum pudding model proposed", "Electrons discovered \u2014 atom must be positive sphere with embedded electrons"], ["Plum pudding model disproved", "Alpha particle scattering \u2014 few particles bounced back, showing small dense nucleus"], ["Nuclear model accepted", "Most particles pass through (empty space) + few bounce back (small dense positive nucleus)"], ["Electrons in fixed shells", "Bohr model \u2014 explains discrete emission spectra and stable electron orbits"]], "title": "Atomic Model Timeline"}, "quiz": {"CF": [{"opts": [["The atom is mostly empty space \u2014 alpha particles encounter nothing to deflect them", true], ["Alpha particles are too fast to be deflected \u2014 their speed carries them through", false], ["Gold atoms have no charge \u2014 nothing to repel the positive alpha particles", false], ["The gold foil was too thin \u2014 a thicker foil would have deflected all particles", false]], "q": "In Rutherford's alpha scattering experiment, most alpha particles passed straight through the gold foil. What does this tell us?", "wrong_explanations": {"1": "Speed could be reduced by using slower particles \u2014 the KEY conclusion is about structure, not speed.", "2": "The FEW particles that DID deflect show gold nuclei ARE positively charged \u2014 most pass through the empty space.", "3": "Thicker foil would increase the probability of deflection, but the fundamental conclusion \u2014 mostly empty space \u2014 remains."}}, {"opts": [["The plum pudding model predicted only small deflections \u2014 the large deflections and back-scattering showed the positive charge must be concentrated in a tiny nucleus", true], ["The plum pudding model predicted all particles would bounce back \u2014 but most passed through", false], ["The plum pudding model had no electrons \u2014 but the experiment detected electrons", false], ["The plum pudding model was proposed after the scattering experiment", false]], "q": "Why did the results of alpha scattering disprove the plum pudding model?", "wrong_explanations": {"1": "The plum pudding model predicted most particles would PASS THROUGH or have SMALL deflections (spread-out positive charge) \u2014 NOT that all would bounce back.", "2": "The plum pudding model DID include electrons \u2014 Thomson discovered them and built them into the model.", "3": "Thomson proposed the plum pudding model in 1904 \u2014 BEFORE Rutherford's 1909 scattering experiment."}}], "CH": [{"opts": [["The atom is mostly empty space \u2014 alpha particles encounter nothing to deflect them", true], ["Alpha particles are too fast to be deflected \u2014 their speed carries them through", false], ["Gold atoms have no charge \u2014 nothing to repel the positive alpha particles", false], ["The gold foil was too thin \u2014 a thicker foil would have deflected all particles", false]], "q": "In Rutherford's alpha scattering experiment, most alpha particles passed straight through the gold foil. What does this tell us?", "wrong_explanations": {"1": "Speed could be reduced by using slower particles \u2014 the KEY conclusion is about structure, not speed.", "2": "The FEW particles that DID deflect show gold nuclei ARE positively charged \u2014 most pass through the empty space.", "3": "Thicker foil would increase the probability of deflection, but the fundamental conclusion \u2014 mostly empty space \u2014 remains."}}, {"opts": [["The plum pudding model predicted only small deflections \u2014 the large deflections and back-scattering showed the positive charge must be concentrated in a tiny nucleus", true], ["The plum pudding model predicted all particles would bounce back \u2014 but most passed through", false], ["The plum pudding model had no electrons \u2014 but the experiment detected electrons", false], ["The plum pudding model was proposed after the scattering experiment", false]], "q": "Why did the results of alpha scattering disprove the plum pudding model?", "wrong_explanations": {"1": "The plum pudding model predicted most particles would PASS THROUGH or have SMALL deflections (spread-out positive charge) \u2014 NOT that all would bounce back.", "2": "The plum pudding model DID include electrons \u2014 Thomson discovered them and built them into the model.", "3": "Thomson proposed the plum pudding model in 1904 \u2014 BEFORE Rutherford's 1909 scattering experiment."}}], "TF": [{"opts": [["The atom is mostly empty space \u2014 alpha particles encounter nothing to deflect them", true], ["Alpha particles are too fast to be deflected \u2014 their speed carries them through", false], ["Gold atoms have no charge \u2014 nothing to repel the positive alpha particles", false], ["The gold foil was too thin \u2014 a thicker foil would have deflected all particles", false]], "q": "In Rutherford's alpha scattering experiment, most alpha particles passed straight through the gold foil. What does this tell us?", "wrong_explanations": {"1": "Speed could be reduced by using slower particles \u2014 the KEY conclusion is about structure, not speed.", "2": "The FEW particles that DID deflect show gold nuclei ARE positively charged \u2014 most pass through the empty space.", "3": "Thicker foil would increase the probability of deflection, but the fundamental conclusion \u2014 mostly empty space \u2014 remains."}}, {"opts": [["The plum pudding model predicted only small deflections \u2014 the large deflections and back-scattering showed the positive charge must be concentrated in a tiny nucleus", true], ["The plum pudding model predicted all particles would bounce back \u2014 but most passed through", false], ["The plum pudding model had no electrons \u2014 but the experiment detected electrons", false], ["The plum pudding model was proposed after the scattering experiment", false]], "q": "Why did the results of alpha scattering disprove the plum pudding model?", "wrong_explanations": {"1": "The plum pudding model predicted most particles would PASS THROUGH or have SMALL deflections (spread-out positive charge) \u2014 NOT that all would bounce back.", "2": "The plum pudding model DID include electrons \u2014 Thomson discovered them and built them into the model.", "3": "Thomson proposed the plum pudding model in 1904 \u2014 BEFORE Rutherford's 1909 scattering experiment."}}], "TH": [{"opts": [["The atom is mostly empty space \u2014 alpha particles encounter nothing to deflect them", true], ["Alpha particles are too fast to be deflected \u2014 their speed carries them through", false], ["Gold atoms have no charge \u2014 nothing to repel the positive alpha particles", false], ["The gold foil was too thin \u2014 a thicker foil would have deflected all particles", false]], "q": "In Rutherford's alpha scattering experiment, most alpha particles passed straight through the gold foil. What does this tell us?", "wrong_explanations": {"1": "Speed could be reduced by using slower particles \u2014 the KEY conclusion is about structure, not speed.", "2": "The FEW particles that DID deflect show gold nuclei ARE positively charged \u2014 most pass through the empty space.", "3": "Thicker foil would increase the probability of deflection, but the fundamental conclusion \u2014 mostly empty space \u2014 remains."}}, {"opts": [["The plum pudding model predicted only small deflections \u2014 the large deflections and back-scattering showed the positive charge must be concentrated in a tiny nucleus", true], ["The plum pudding model predicted all particles would bounce back \u2014 but most passed through", false], ["The plum pudding model had no electrons \u2014 but the experiment detected electrons", false], ["The plum pudding model was proposed after the scattering experiment", false]], "q": "Why did the results of alpha scattering disprove the plum pudding model?", "wrong_explanations": {"1": "The plum pudding model predicted most particles would PASS THROUGH or have SMALL deflections (spread-out positive charge) \u2014 NOT that all would bounce back.", "2": "The plum pudding model DID include electrons \u2014 Thomson discovered them and built them into the model.", "3": "Thomson proposed the plum pudding model in 1904 \u2014 BEFORE Rutherford's 1909 scattering experiment."}}]}, "summary": "Describe how the model of the atom developed from solid sphere to nuclear model.", "theory": [{"content": "Before the late 1800s, atoms were thought to be TINY SOLID SPHERES that could not be divided \u2014 the smallest possible particles of matter.\n\nThis model had no internal structure \u2014 atoms were indivisible 'billiard balls'.\n\nThis model was replaced when ELECTRONS were discovered.\n\nDISCOVERY OF THE ELECTRON (J.J. Thomson, 1897):\nThomson used cathode rays \u2014 beams of particles deflected by electric and magnetic fields.\nThe particles (electrons) were the same regardless of the cathode material \u2192 electrons are part of all atoms.\nElectrons have negative charge and very small mass.\n\nThis proved atoms CAN be divided \u2014 they have internal structure.\nThe solid sphere model was abandoned.", "heading": "The Solid Sphere Model"}, {"content": "After Thomson's discovery, he proposed the PLUM PUDDING MODEL:\nThe atom is a BALL OF POSITIVE CHARGE (the 'pudding').\nNEGATIVE ELECTRONS are embedded within it (the 'plums').\nThe overall charge is neutral.\n\nThis seemed reasonable \u2014 it explained that atoms have electrons but are overall neutral.\n\nHowever, this model was soon disproved by an important experiment.\n\nRUTHERFORD'S ALPHA PARTICLE SCATTERING EXPERIMENT (1909, Geiger and Marsden):\nAlpha particles fired at a very thin gold foil.\nExpected result (plum pudding): all alpha particles would pass straight through or deflect only slightly (spread-out positive charge).\nActual result: MOST passed straight through; a SMALL NUMBER deflected through large angles; a VERY FEW bounced back almost 180\u00b0.\n\nRutherford's famous quote: 'It was as if you fired a 15-inch shell at tissue paper and it came back and hit you.'", "heading": "The Plum Pudding Model"}, {"content": "The scattering results led to the NUCLEAR MODEL (Rutherford, 1911):\n\nConclusions from the experiment:\nMOST particles passed straight through \u2192 atom is MOSTLY EMPTY SPACE.\nSOME deflected through large angles \u2192 there is a concentrated region of POSITIVE CHARGE.\nVERY FEW bounced back \u2192 the positive charge is very SMALL and very DENSE.\n\nThe NUCLEAR MODEL:\nSmall, dense, positively charged NUCLEUS at the centre.\nElectrons orbit the nucleus at relatively large distances.\nMost of the atom is empty space.\n\nFURTHER DEVELOPMENTS:\nBohr (1913): electrons orbit in fixed shells (energy levels) \u2014 explains why atoms don't collapse and why emission spectra have discrete lines.\nChadwick (1932): discovered the NEUTRON \u2014 explained why nuclei are heavier than just protons alone.\n\nSCIENCE PRINCIPLE:\nNew experimental evidence leads to models being changed or replaced.\nThe atomic model changed as new evidence emerged \u2014 showing how science is self-correcting.", "heading": "The Nuclear Model"}]};
window.KS4SRC["global-warming"] = {"common_mistake": "In BIOLOGY, focus on the LIVING consequences of global warming \u2014 changes in species distribution, migration, and biodiversity \u2014 not just the greenhouse-gas chemistry. Also, 'distribution' means WHERE a species lives (its range), not how many there are. Rising sea level is caused by BOTH melting ice AND warm water expanding.", "key_note": "Rising CO\u2082 and methane (greenhouse gases) trap heat \u2192 global warming. Biological consequences: changed species distribution, altered migration patterns, rising sea levels flooding habitats, and reduced biodiversity. Evidence comes from global data; treat model predictions with appropriate caution.", "matching": {"instruction": "Sort each into a cause of global warming or a biological effect of it.", "pairs": [["Cause", "Rising carbon dioxide from burning fossil fuels"], ["Cause", "Rising methane from livestock farming"], ["Cause", "Deforestation reducing CO\u2082 absorption"], ["Biological effect", "Species distribution shifting towards the poles"], ["Biological effect", "Changes in bird migration timing"], ["Biological effect", "Coastal habitats lost as sea levels rise"]], "title": "Global Warming: Cause or Effect?"}, "quiz": {"CF": [{"opts": [["The geographic area where the species is found", true], ["The total number of individuals in the species", false], ["How the food is shared within a population", false], ["The genetic variety within the species", false]], "q": "Global warming changes the \"distribution\" of a species. What does distribution mean?", "wrong_explanations": {"1": "Distribution is the range \u2014 the places on Earth where a species lives. Warming shifts this range.", "2": "That is population size, not distribution.", "3": "That is not what distribution means in ecology."}}, {"opts": [["Melting ice and thermal expansion of warmer water", true], ["Photosynthesis and respiration", false], ["More rain falling on land", false], ["Fish releasing carbon dioxide", false]], "q": "Which pair of processes is causing sea levels to rise?", "wrong_explanations": {"1": "Warming melts land ice (adding water) and makes existing sea water expand as it warms \u2014 both raise sea level.", "2": "Photosynthesis and respiration cycle carbon; they do not raise sea level.", "3": "Rainfall does not cause the long-term rise; melting ice and thermal expansion do."}}], "CH": [{"opts": [["The geographic area where the species is found", true], ["The total number of individuals in the species", false], ["How the food is shared within a population", false], ["The genetic variety within the species", false]], "q": "Global warming changes the \"distribution\" of a species. What does distribution mean?", "wrong_explanations": {"1": "Distribution is the range \u2014 the places on Earth where a species lives. Warming shifts this range.", "2": "That is population size, not distribution.", "3": "That is not what distribution means in ecology."}}, {"opts": [["Melting ice and thermal expansion of warmer water", true], ["Photosynthesis and respiration", false], ["More rain falling on land", false], ["Fish releasing carbon dioxide", false]], "q": "Which pair of processes is causing sea levels to rise?", "wrong_explanations": {"1": "Warming melts land ice (adding water) and makes existing sea water expand as it warms \u2014 both raise sea level.", "2": "Photosynthesis and respiration cycle carbon; they do not raise sea level.", "3": "Rainfall does not cause the long-term rise; melting ice and thermal expansion do."}}], "TF": [{"opts": [["The geographic area where the species is found", true], ["The total number of individuals in the species", false], ["How the food is shared within a population", false], ["The genetic variety within the species", false]], "q": "Global warming changes the \"distribution\" of a species. What does distribution mean?", "wrong_explanations": {"1": "Distribution is the range \u2014 the places on Earth where a species lives. Warming shifts this range.", "2": "That is population size, not distribution.", "3": "That is not what distribution means in ecology."}}, {"opts": [["Melting ice and thermal expansion of warmer water", true], ["Photosynthesis and respiration", false], ["More rain falling on land", false], ["Fish releasing carbon dioxide", false]], "q": "Which pair of processes is causing sea levels to rise?", "wrong_explanations": {"1": "Warming melts land ice (adding water) and makes existing sea water expand as it warms \u2014 both raise sea level.", "2": "Photosynthesis and respiration cycle carbon; they do not raise sea level.", "3": "Rainfall does not cause the long-term rise; melting ice and thermal expansion do."}}], "TH": [{"opts": [["The geographic area where the species is found", true], ["The total number of individuals in the species", false], ["How the food is shared within a population", false], ["The genetic variety within the species", false]], "q": "Global warming changes the \"distribution\" of a species. What does distribution mean?", "wrong_explanations": {"1": "Distribution is the range \u2014 the places on Earth where a species lives. Warming shifts this range.", "2": "That is population size, not distribution.", "3": "That is not what distribution means in ecology."}}, {"opts": [["Melting ice and thermal expansion of warmer water", true], ["Photosynthesis and respiration", false], ["More rain falling on land", false], ["Fish releasing carbon dioxide", false]], "q": "Which pair of processes is causing sea levels to rise?", "wrong_explanations": {"1": "Warming melts land ice (adding water) and makes existing sea water expand as it warms \u2014 both raise sea level.", "2": "Photosynthesis and respiration cycle carbon; they do not raise sea level.", "3": "Rainfall does not cause the long-term rise; melting ice and thermal expansion do."}}]}, "summary": "Describe how rising carbon dioxide and methane cause global warming, and explain its biological consequences for species distribution, migration and biodiversity.", "theory": [{"content": "The levels of CARBON DIOXIDE and METHANE in the atmosphere are INCREASING.\n\nThese are GREENHOUSE GASES \u2014 they trap heat energy near the Earth's surface.\n\nAs their levels rise, more heat is trapped, so the Earth's average temperature is increasing. This is GLOBAL WARMING.\n\nHuman activities that raise these gases include burning fossil fuels, deforestation, and farming livestock (which produce methane).", "heading": "What is causing global warming"}, {"content": "Global warming has serious effects on living things:\n\nCHANGES IN DISTRIBUTION \u2014 as temperatures change, some species can no longer survive where they used to live, so their geographic range shifts (often towards the poles or higher ground).\n\nCHANGES IN MIGRATION PATTERNS \u2014 migrating animals (e.g. birds) may arrive earlier or travel to different places as seasons shift.\n\nRISING SEA LEVELS \u2014 melting ice and the expansion of warmer water raise sea levels, flooding coastal HABITATS.\n\nREDUCED BIODIVERSITY \u2014 species that cannot move or adapt fast enough may become extinct.", "heading": "Biological consequences"}, {"content": "Scientists collect DATA on temperature, CO\u2082 levels, ice cover and species ranges from all over the world.\n\nThere is strong evidence that human activity is causing global warming.\n\nWe must be careful about UNCERTAINTIES \u2014 climate is complex and predictions rely on models \u2014 but the overall trend is clear.\n\nYou should be able to read graphs of these data and describe what they show without overstating certainty.", "heading": "Evaluating the evidence"}]};
window.KS4SRC["group-0"] = {"common_mistake": "Noble gases are MONATOMIC \u2014 they exist as single atoms (He, Ne, Ar) \u2014 NOT as molecules (not He\u2082 or Ne\u2082). This is because they are already stable with full outer shells and have no reason to form bonds. Other non-metals like oxygen (O\u2082) and nitrogen (N\u2082) exist as diatomic molecules because they share electrons to achieve full outer shells.", "key_note": "Noble gases: Group 0, full outer shells, extremely unreactive, monatomic. Boiling point increases down group (bigger atoms, stronger London dispersion forces). Helium: 2 outer electrons (full 1st shell). All others: 8 outer electrons (full outer shell).", "matching": {"instruction": "Match each property to noble gases and explain why.", "pairs": [["Very unreactive", "Full outer electron shells \u2014 no tendency to gain, lose or share electrons"], ["Monatomic", "Exist as single atoms \u2014 already stable, no need to bond with other atoms"], ["Boiling point increases down group", "Larger atoms have stronger London dispersion forces \u2014 more electrons, larger temporary dipoles"], ["Colourless gases", "All noble gases are transparent and gaseous at room temperature"], ["Helium \u2014 lighter than air", "Helium has only 2 electrons and 2 protons \u2014 very low density, used in balloons"]], "title": "Match the Noble Gas Property"}, "quiz": {"CF": [{"opts": [["They have full outer electron shells \u2014 no tendency to gain, lose or share electrons to become more stable", true], ["They are gases \u2014 gases cannot react with solid or liquid substances", false], ["They have no electrons in their outer shell \u2014 so they cannot form bonds", false], ["They are too small to collide effectively with other atoms", false]], "q": "Why are noble gases so unreactive?", "wrong_explanations": {"1": "Many gases are highly reactive \u2014 chlorine gas (Cl\u2082), oxygen gas (O\u2082) etc. Being a gas doesn't make something unreactive.", "2": "Noble gases have FULL outer shells, not empty ones. Helium has 2 electrons (full 1st shell), others have 8 outer electrons.", "3": "Atomic size affects reactivity in some cases, but noble gases are unreactive because of electron configuration, not size."}}, {"opts": [["Argon is a larger atom with more electrons \u2014 stronger London dispersion forces between atoms need more energy to overcome", true], ["Argon has a higher atomic number, so its electrons are more strongly attracted to the nucleus", false], ["Argon forms molecules (Ar\u2082) while neon is monatomic \u2014 more bonds to break", false], ["Argon is radioactive, releasing energy that raises its boiling point", false]], "q": "Argon has a higher boiling point than neon. Why?", "wrong_explanations": {"1": "Stronger nuclear attraction would make electrons harder to remove but doesn't directly raise boiling point \u2014 the intermolecular forces between atoms are what matter.", "2": "Noble gases are ALL monatomic \u2014 they never form Ar\u2082 or Ne\u2082 molecules under normal conditions.", "3": "Argon is stable and not radioactive. Radon is the radioactive noble gas."}}], "CH": [{"opts": [["They have full outer electron shells \u2014 no tendency to gain, lose or share electrons to become more stable", true], ["They are gases \u2014 gases cannot react with solid or liquid substances", false], ["They have no electrons in their outer shell \u2014 so they cannot form bonds", false], ["They are too small to collide effectively with other atoms", false]], "q": "Why are noble gases so unreactive?", "wrong_explanations": {"1": "Many gases are highly reactive \u2014 chlorine gas (Cl\u2082), oxygen gas (O\u2082) etc. Being a gas doesn't make something unreactive.", "2": "Noble gases have FULL outer shells, not empty ones. Helium has 2 electrons (full 1st shell), others have 8 outer electrons.", "3": "Atomic size affects reactivity in some cases, but noble gases are unreactive because of electron configuration, not size."}}, {"opts": [["Argon is a larger atom with more electrons \u2014 stronger London dispersion forces between atoms need more energy to overcome", true], ["Argon has a higher atomic number, so its electrons are more strongly attracted to the nucleus", false], ["Argon forms molecules (Ar\u2082) while neon is monatomic \u2014 more bonds to break", false], ["Argon is radioactive, releasing energy that raises its boiling point", false]], "q": "Argon has a higher boiling point than neon. Why?", "wrong_explanations": {"1": "Stronger nuclear attraction would make electrons harder to remove but doesn't directly raise boiling point \u2014 the intermolecular forces between atoms are what matter.", "2": "Noble gases are ALL monatomic \u2014 they never form Ar\u2082 or Ne\u2082 molecules under normal conditions.", "3": "Argon is stable and not radioactive. Radon is the radioactive noble gas."}}], "TF": [{"opts": [["They have full outer electron shells \u2014 no tendency to gain, lose or share electrons to become more stable", true], ["They are gases \u2014 gases cannot react with solid or liquid substances", false], ["They have no electrons in their outer shell \u2014 so they cannot form bonds", false], ["They are too small to collide effectively with other atoms", false]], "q": "Why are noble gases so unreactive?", "wrong_explanations": {"1": "Many gases are highly reactive \u2014 chlorine gas (Cl\u2082), oxygen gas (O\u2082) etc. Being a gas doesn't make something unreactive.", "2": "Noble gases have FULL outer shells, not empty ones. Helium has 2 electrons (full 1st shell), others have 8 outer electrons.", "3": "Atomic size affects reactivity in some cases, but noble gases are unreactive because of electron configuration, not size."}}, {"opts": [["Argon is a larger atom with more electrons \u2014 stronger London dispersion forces between atoms need more energy to overcome", true], ["Argon has a higher atomic number, so its electrons are more strongly attracted to the nucleus", false], ["Argon forms molecules (Ar\u2082) while neon is monatomic \u2014 more bonds to break", false], ["Argon is radioactive, releasing energy that raises its boiling point", false]], "q": "Argon has a higher boiling point than neon. Why?", "wrong_explanations": {"1": "Stronger nuclear attraction would make electrons harder to remove but doesn't directly raise boiling point \u2014 the intermolecular forces between atoms are what matter.", "2": "Noble gases are ALL monatomic \u2014 they never form Ar\u2082 or Ne\u2082 molecules under normal conditions.", "3": "Argon is stable and not radioactive. Radon is the radioactive noble gas."}}], "TH": [{"opts": [["They have full outer electron shells \u2014 no tendency to gain, lose or share electrons to become more stable", true], ["They are gases \u2014 gases cannot react with solid or liquid substances", false], ["They have no electrons in their outer shell \u2014 so they cannot form bonds", false], ["They are too small to collide effectively with other atoms", false]], "q": "Why are noble gases so unreactive?", "wrong_explanations": {"1": "Many gases are highly reactive \u2014 chlorine gas (Cl\u2082), oxygen gas (O\u2082) etc. Being a gas doesn't make something unreactive.", "2": "Noble gases have FULL outer shells, not empty ones. Helium has 2 electrons (full 1st shell), others have 8 outer electrons.", "3": "Atomic size affects reactivity in some cases, but noble gases are unreactive because of electron configuration, not size."}}, {"opts": [["Argon is a larger atom with more electrons \u2014 stronger London dispersion forces between atoms need more energy to overcome", true], ["Argon has a higher atomic number, so its electrons are more strongly attracted to the nucleus", false], ["Argon forms molecules (Ar\u2082) while neon is monatomic \u2014 more bonds to break", false], ["Argon is radioactive, releasing energy that raises its boiling point", false]], "q": "Argon has a higher boiling point than neon. Why?", "wrong_explanations": {"1": "Stronger nuclear attraction would make electrons harder to remove but doesn't directly raise boiling point \u2014 the intermolecular forces between atoms are what matter.", "2": "Noble gases are ALL monatomic \u2014 they never form Ar\u2082 or Ne\u2082 molecules under normal conditions.", "3": "Argon is stable and not radioactive. Radon is the radioactive noble gas."}}]}, "summary": "Describe the properties of noble gases and explain why they are so unreactive.", "theory": [{"content": "GROUP 0 (also called Group 18) contains the NOBLE GASES:\nHelium (He) \u2014 atomic number 2.\nNeon (Ne) \u2014 atomic number 10.\nArgon (Ar) \u2014 atomic number 18.\nKrypton (Kr) \u2014 atomic number 36.\nXenon (Xe) \u2014 atomic number 54.\nRadon (Rn) \u2014 atomic number 86.\n\nAll noble gases are:\nCOLOURLESS gases at room temperature.\nMONATOMIC \u2014 they exist as single atoms, not molecules (unlike O\u2082, N\u2082, Cl\u2082).\nEXTREMELY UNREACTIVE \u2014 they do not form compounds under normal conditions.\nDENSER than air as you go down the group.\nHave very LOW BOILING POINTS \u2014 they remain gases until very cold.", "heading": "Properties of the Noble Gases"}, {"content": "Noble gases are unreactive because they have FULL OUTER ELECTRON SHELLS:\nHelium: 2 electrons (full 1st shell).\nNeon: 2.8 (full 1st and 2nd shells).\nArgon: 2.8.8 (full 1st, 2nd and 3rd shells).\n\nA full outer shell is the most STABLE electron configuration \u2014 the atom has no tendency to gain, lose or share electrons.\n\nThis is why other elements react \u2014 they are trying to ACHIEVE the stable full outer shell configuration of a noble gas:\nGroup 1 metals lose 1 electron \u2192 achieve noble gas configuration.\nGroup 7 non-metals gain 1 electron \u2192 achieve noble gas configuration.\nNon-metals share electrons (covalent bonds) to achieve full outer shells.", "heading": "Why Noble Gases Are Unreactive"}, {"content": "Going DOWN Group 0 (from He to Rn):\n\nATOMIC RADIUS increases \u2014 more electron shells are added.\n\nBOILING POINT INCREASES:\nHe: \u2212269\u00b0C, Ne: \u2212246\u00b0C, Ar: \u2212186\u00b0C, Kr: \u2212153\u00b0C, Xe: \u2212108\u00b0C.\nLarger atoms have stronger LONDON DISPERSION FORCES between them (a type of intermolecular force caused by temporary dipoles in electron clouds).\nMore electrons \u2192 greater temporary dipoles \u2192 stronger forces \u2192 higher boiling point.\n\nDENSITY increases down the group.\n\nThe reactivity stays VERY LOW throughout \u2014 all noble gases are essentially inert under normal conditions.", "heading": "Trends Down Group 0"}]};
window.KS4SRC["extraction-of-metals"] = {"common_mistake": "Aluminium is above carbon in the reactivity series \u2014 carbon CANNOT reduce aluminium oxide. Students often try to apply carbon reduction to all metals. Only metals BELOW carbon in the reactivity series can be extracted by carbon reduction. Metals above carbon (including aluminium) require electrolysis.", "equations": ["Fe\u2082O\u2083 + 3CO \u2192 2Fe + 3CO\u2082  (iron extraction)", "ZnO + C \u2192 Zn + CO\u2082", "2Al\u2082O\u2083 \u2192 4Al + 3O\u2082  (electrolysis of aluminium oxide)"], "higher": "Evaluate economic and environmental factors: energy cost of electrolysis vs smelting, environmental impact of mining, transportation costs. Compare traditional vs alternative methods (phytomining, bioleaching) in terms of speed, cost, environmental impact and suitability for ore grade.", "key_note": "Extraction method depends on reactivity. Above carbon in series \u2192 electrolysis (Al, Mg, Na etc.). Below carbon \u2192 reduction with carbon/CO (Fe, Zn etc.). Unreactive metals \u2192 found native or simple reduction. Iron: blast furnace with CO. Aluminium: electrolysis of molten Al\u2082O\u2083 in cryolite.", "matching": {"instruction": "Match each metal to how it is extracted from its ore.", "pairs": [["Iron", "Reduced with carbon monoxide in a blast furnace \u2014 below carbon in reactivity series"], ["Aluminium", "Electrolysis of molten Al\u2082O\u2083 in cryolite \u2014 above carbon in reactivity series"], ["Gold", "Found as the pure element \u2014 too unreactive to form stable compounds"], ["Zinc", "Heated with carbon/coke \u2014 ZnO + C \u2192 Zn + CO\u2082"], ["Sodium", "Electrolysis of molten NaCl \u2014 far too reactive for carbon reduction"]], "title": "Match the Metal to its Extraction Method"}, "quiz": {"CF": [{"opts": [["Aluminium is more reactive than carbon \u2014 carbon cannot displace it from aluminium oxide", true], ["Aluminium oxide doesn't contain enough oxygen for the carbon to react with", false], ["Carbon would contaminate the aluminium, making it too brittle to use", false], ["Electrolysis is cheaper than heating with carbon for all metals", false]], "q": "Why is aluminium extracted by electrolysis rather than by reduction with carbon?", "wrong_explanations": {"1": "Aluminium oxide has plenty of oxygen \u2014 but carbon can only REDUCE metal oxides when the metal is LESS reactive than carbon.", "2": "Carbon and aluminium do not form harmful alloys under these conditions \u2014 purity concerns are a separate issue.", "3": "Electrolysis is actually VERY EXPENSIVE \u2014 it requires huge amounts of electrical energy. The reason is purely reactivity-based."}}, {"opts": [["Reduction \u2014 the iron oxide loses oxygen; the carbon monoxide gains oxygen (and is oxidised)", true], ["Oxidation \u2014 the iron oxide gains electrons from the carbon monoxide", false], ["Neutralisation \u2014 the acid iron oxide is neutralised by the basic carbon", false], ["Electrolysis \u2014 electrical energy breaks apart the iron oxide", false]], "q": "Carbon monoxide reduces iron oxide in the blast furnace. What type of reaction is this?", "wrong_explanations": {"1": "The IRON OXIDE loses oxygen (is REDUCED). The CO gains oxygen (is OXIDISED). These are simultaneous \u2014 the reaction is both a reduction AND an oxidation.", "2": "Neutralisation involves an acid and a base \u2014 iron oxide and carbon monoxide are not an acid-base pair.", "3": "The blast furnace uses heat (combustion), not electricity. Electrolysis is used for reactive metals like aluminium."}}], "CH": [{"opts": [["Aluminium is more reactive than carbon \u2014 carbon cannot displace it from aluminium oxide", true], ["Aluminium oxide doesn't contain enough oxygen for the carbon to react with", false], ["Carbon would contaminate the aluminium, making it too brittle to use", false], ["Electrolysis is cheaper than heating with carbon for all metals", false]], "q": "Why is aluminium extracted by electrolysis rather than by reduction with carbon?", "wrong_explanations": {"1": "Aluminium oxide has plenty of oxygen \u2014 but carbon can only REDUCE metal oxides when the metal is LESS reactive than carbon.", "2": "Carbon and aluminium do not form harmful alloys under these conditions \u2014 purity concerns are a separate issue.", "3": "Electrolysis is actually VERY EXPENSIVE \u2014 it requires huge amounts of electrical energy. The reason is purely reactivity-based."}}, {"opts": [["Reduction \u2014 the iron oxide loses oxygen; the carbon monoxide gains oxygen (and is oxidised)", true], ["Oxidation \u2014 the iron oxide gains electrons from the carbon monoxide", false], ["Neutralisation \u2014 the acid iron oxide is neutralised by the basic carbon", false], ["Electrolysis \u2014 electrical energy breaks apart the iron oxide", false]], "q": "Carbon monoxide reduces iron oxide in the blast furnace. What type of reaction is this?", "wrong_explanations": {"1": "The IRON OXIDE loses oxygen (is REDUCED). The CO gains oxygen (is OXIDISED). These are simultaneous \u2014 the reaction is both a reduction AND an oxidation.", "2": "Neutralisation involves an acid and a base \u2014 iron oxide and carbon monoxide are not an acid-base pair.", "3": "The blast furnace uses heat (combustion), not electricity. Electrolysis is used for reactive metals like aluminium."}}], "TF": [{"opts": [["Aluminium is more reactive than carbon \u2014 carbon cannot displace it from aluminium oxide", true], ["Aluminium oxide doesn't contain enough oxygen for the carbon to react with", false], ["Carbon would contaminate the aluminium, making it too brittle to use", false], ["Electrolysis is cheaper than heating with carbon for all metals", false]], "q": "Why is aluminium extracted by electrolysis rather than by reduction with carbon?", "wrong_explanations": {"1": "Aluminium oxide has plenty of oxygen \u2014 but carbon can only REDUCE metal oxides when the metal is LESS reactive than carbon.", "2": "Carbon and aluminium do not form harmful alloys under these conditions \u2014 purity concerns are a separate issue.", "3": "Electrolysis is actually VERY EXPENSIVE \u2014 it requires huge amounts of electrical energy. The reason is purely reactivity-based."}}, {"opts": [["Reduction \u2014 the iron oxide loses oxygen; the carbon monoxide gains oxygen (and is oxidised)", true], ["Oxidation \u2014 the iron oxide gains electrons from the carbon monoxide", false], ["Neutralisation \u2014 the acid iron oxide is neutralised by the basic carbon", false], ["Electrolysis \u2014 electrical energy breaks apart the iron oxide", false]], "q": "Carbon monoxide reduces iron oxide in the blast furnace. What type of reaction is this?", "wrong_explanations": {"1": "The IRON OXIDE loses oxygen (is REDUCED). The CO gains oxygen (is OXIDISED). These are simultaneous \u2014 the reaction is both a reduction AND an oxidation.", "2": "Neutralisation involves an acid and a base \u2014 iron oxide and carbon monoxide are not an acid-base pair.", "3": "The blast furnace uses heat (combustion), not electricity. Electrolysis is used for reactive metals like aluminium."}}], "TH": [{"opts": [["Aluminium is more reactive than carbon \u2014 carbon cannot displace it from aluminium oxide", true], ["Aluminium oxide doesn't contain enough oxygen for the carbon to react with", false], ["Carbon would contaminate the aluminium, making it too brittle to use", false], ["Electrolysis is cheaper than heating with carbon for all metals", false]], "q": "Why is aluminium extracted by electrolysis rather than by reduction with carbon?", "wrong_explanations": {"1": "Aluminium oxide has plenty of oxygen \u2014 but carbon can only REDUCE metal oxides when the metal is LESS reactive than carbon.", "2": "Carbon and aluminium do not form harmful alloys under these conditions \u2014 purity concerns are a separate issue.", "3": "Electrolysis is actually VERY EXPENSIVE \u2014 it requires huge amounts of electrical energy. The reason is purely reactivity-based."}}, {"opts": [["Reduction \u2014 the iron oxide loses oxygen; the carbon monoxide gains oxygen (and is oxidised)", true], ["Oxidation \u2014 the iron oxide gains electrons from the carbon monoxide", false], ["Neutralisation \u2014 the acid iron oxide is neutralised by the basic carbon", false], ["Electrolysis \u2014 electrical energy breaks apart the iron oxide", false]], "q": "Carbon monoxide reduces iron oxide in the blast furnace. What type of reaction is this?", "wrong_explanations": {"1": "The IRON OXIDE loses oxygen (is REDUCED). The CO gains oxygen (is OXIDISED). These are simultaneous \u2014 the reaction is both a reduction AND an oxidation.", "2": "Neutralisation involves an acid and a base \u2014 iron oxide and carbon monoxide are not an acid-base pair.", "3": "The blast furnace uses heat (combustion), not electricity. Electrolysis is used for reactive metals like aluminium."}}]}, "summary": "Explain how metals are extracted from their ores and how the method depends on reactivity.", "theory": [{"content": "Most metals are found in nature as ORES \u2014 rocks containing metal compounds (usually oxides, sulfides or carbonates) rather than pure metals.\n\nOnly very UNREACTIVE metals (gold, platinum, silver) are found as pure elements in nature \u2014 they are too unreactive to form compounds with oxygen or sulfur.\n\nAll other metals must be EXTRACTED from their ores \u2014 the metal compound must be converted back to a pure metal.\n\nThe REACTIVITY of the metal determines the EXTRACTION METHOD:\nVERY REACTIVE metals (K, Na, Ca, Mg, Al) \u2014 cannot be extracted by carbon reduction because they are more reactive than carbon. Must use ELECTROLYSIS of molten compounds.\n\nMODERATELY REACTIVE metals BELOW carbon in the series (Zn, Fe, Sn, Pb) \u2014 can be extracted by heating their oxide with CARBON (reduction).\n\nUNREACTIVE metals (Cu, Ag, Au) \u2014 found native (as pure elements) or can be extracted by simple reduction or displacement.", "heading": "Why Metals Need to be Extracted"}, {"content": "REDUCTION WITH CARBON (also called SMELTING) works for metals below carbon in the reactivity series.\n\nCarbon displaces these metals from their oxides because carbon is MORE REACTIVE than these metals.\n\nIRON FROM IRON OXIDE (Blast Furnace):\nIron ore (mainly haematite: Fe\u2082O\u2083) is heated with coke (carbon) and limestone in a blast furnace.\nCarbon reacts with oxygen to form carbon dioxide:\nC + O\u2082 \u2192 CO\u2082\nCO\u2082 then reacts with more carbon to form carbon monoxide:\nCO\u2082 + C \u2192 2CO\nCarbon monoxide REDUCES iron oxide to iron:\nFe\u2082O\u2083 + 3CO \u2192 2Fe + 3CO\u2082\nMolten iron sinks to the bottom of the furnace and is tapped off.\n\nZINC EXTRACTION:\nZnO + C \u2192 Zn + CO\u2082\n\nALUMINIUM CANNOT be extracted this way \u2014 it is above carbon in the reactivity series and must use electrolysis.", "heading": "Reduction with Carbon \u2014 Blast Furnace"}, {"content": "ELECTROLYSIS is used for metals that are MORE REACTIVE than carbon (K, Na, Li, Ca, Mg, Al).\n\nThese metals form very stable compounds \u2014 carbon cannot reduce them.\nInstead, electrical energy is used to decompose the molten compound.\n\nALUMINIUM EXTRACTION (Hall-H\u00e9roult process):\nAluminium oxide (Al\u2082O\u2083) \u2014 also called alumina \u2014 is dissolved in molten cryolite (to lower the melting point from ~2000\u00b0C to ~950\u00b0C).\nElectrolysis takes place:\nAt CATHODE (negative): Al\u00b3\u207a + 3e\u207b \u2192 Al (aluminium deposited)\nAt ANODE (positive): O\u00b2\u207b \u2192 O\u2082 (oxygen gas produced)\nMolten aluminium sinks to the bottom and is tapped off.\n\nWhy electrolysis is expensive:\nHuge amounts of ELECTRICAL ENERGY needed.\nThe process must run continuously at high temperatures.\nThe carbon anodes react with oxygen and must be REPLACED regularly.\n\nThis is why aluminium was once more expensive than gold \u2014 before cheap electricity, it was extremely difficult to extract.", "heading": "Electrolysis for Reactive Metals"}]};
window.KS4SRC["potable-water"] = {"common_mistake": "Potable water is NOT the same as PURE water. Potable = safe to drink (low levels of dissolved minerals and microbes). Pure = only H\u2082O. Tap water is potable but not chemically pure \u2014 it contains dissolved calcium, chlorine, fluoride etc. Distilled water is pure but not ideal for drinking long-term (lacks minerals).", "higher": "Evaluate desalination methods: distillation vs reverse osmosis \u2014 compare energy requirements, scalability, applicability. Reverse osmosis: pressure forces water through semi-permeable membrane against osmotic gradient. UV and ozone as chlorine alternatives \u2014 advantages (no by-products) vs disadvantages (cost, no residual protection).", "key_note": "Potable water: safe to drink (not pure). UK fresh water treatment: sedimentation \u2192 filtration \u2192 chlorination. Desalination (seawater): distillation or reverse osmosis \u2014 expensive and energy-intensive. Sewage treatment: screening \u2192 sedimentation \u2192 aerobic digestion \u2192 sludge anaerobic digestion (produces biogas) \u2192 chlorination.", "matching": {"instruction": "Match each water treatment step to what it removes.", "pairs": [["Sedimentation", "Large particles and suspended solids \u2014 allowed to settle or clump and sink"], ["Filtration (sand/gravel)", "Finer particles and some microorganisms \u2014 physically filtered out"], ["Chlorination", "Harmful microorganisms (bacteria and viruses) \u2014 killed by chlorine"], ["Screening (sewage)", "Large solids \u2014 removed by physical screens at the start of sewage treatment"], ["Anaerobic digestion", "Organic matter in sludge \u2014 produces biogas (methane) as a useful by-product"]], "title": "Water Treatment Steps"}, "quiz": {"CF": [{"opts": [["Potable water contains low levels of dissolved minerals and is safe to drink \u2014 pure water contains only H\u2082O molecules", true], ["Potable water has been boiled \u2014 pure water has not been heated", false], ["Pure water is safe to drink \u2014 potable water contains pollutants", false], ["Potable water is seawater that has been filtered \u2014 pure water comes from rainfall only", false]], "q": "Why is potable water NOT the same as pure water?", "wrong_explanations": {"1": "Boiling is used in distillation to purify water \u2014 but potable water is not defined by whether it has been boiled.", "2": "It's the other way round \u2014 PURE water is chemically pure (H\u2082O only). POTABLE water is safe to drink but contains minerals.", "3": "Potable water comes from rivers, reservoirs, boreholes \u2014 not primarily seawater. Pure water is the chemically pure form."}}, {"opts": [["Biogas (mainly methane) \u2014 can be used as a renewable fuel", true], ["Pure water \u2014 the sludge is distilled", false], ["Fertiliser only \u2014 no gas is produced anaerobically", false], ["Chlorine \u2014 used to disinfect the remaining water", false]], "q": "What useful product is obtained from anaerobic digestion of sewage sludge?", "wrong_explanations": {"1": "Distillation is used to purify water, not to treat sludge \u2014 the anaerobic digestion process produces GAS, not water.", "2": "Anaerobic digestion of sludge produces BOTH biogas AND digestate (solid fertiliser) \u2014 the gas is a key economic benefit.", "3": "Chlorine is added separately at the end of water treatment \u2014 it is not produced during anaerobic digestion."}}], "CH": [{"opts": [["Potable water contains low levels of dissolved minerals and is safe to drink \u2014 pure water contains only H\u2082O molecules", true], ["Potable water has been boiled \u2014 pure water has not been heated", false], ["Pure water is safe to drink \u2014 potable water contains pollutants", false], ["Potable water is seawater that has been filtered \u2014 pure water comes from rainfall only", false]], "q": "Why is potable water NOT the same as pure water?", "wrong_explanations": {"1": "Boiling is used in distillation to purify water \u2014 but potable water is not defined by whether it has been boiled.", "2": "It's the other way round \u2014 PURE water is chemically pure (H\u2082O only). POTABLE water is safe to drink but contains minerals.", "3": "Potable water comes from rivers, reservoirs, boreholes \u2014 not primarily seawater. Pure water is the chemically pure form."}}, {"opts": [["Biogas (mainly methane) \u2014 can be used as a renewable fuel", true], ["Pure water \u2014 the sludge is distilled", false], ["Fertiliser only \u2014 no gas is produced anaerobically", false], ["Chlorine \u2014 used to disinfect the remaining water", false]], "q": "What useful product is obtained from anaerobic digestion of sewage sludge?", "wrong_explanations": {"1": "Distillation is used to purify water, not to treat sludge \u2014 the anaerobic digestion process produces GAS, not water.", "2": "Anaerobic digestion of sludge produces BOTH biogas AND digestate (solid fertiliser) \u2014 the gas is a key economic benefit.", "3": "Chlorine is added separately at the end of water treatment \u2014 it is not produced during anaerobic digestion."}}], "TF": [{"opts": [["Potable water contains low levels of dissolved minerals and is safe to drink \u2014 pure water contains only H\u2082O molecules", true], ["Potable water has been boiled \u2014 pure water has not been heated", false], ["Pure water is safe to drink \u2014 potable water contains pollutants", false], ["Potable water is seawater that has been filtered \u2014 pure water comes from rainfall only", false]], "q": "Why is potable water NOT the same as pure water?", "wrong_explanations": {"1": "Boiling is used in distillation to purify water \u2014 but potable water is not defined by whether it has been boiled.", "2": "It's the other way round \u2014 PURE water is chemically pure (H\u2082O only). POTABLE water is safe to drink but contains minerals.", "3": "Potable water comes from rivers, reservoirs, boreholes \u2014 not primarily seawater. Pure water is the chemically pure form."}}, {"opts": [["Biogas (mainly methane) \u2014 can be used as a renewable fuel", true], ["Pure water \u2014 the sludge is distilled", false], ["Fertiliser only \u2014 no gas is produced anaerobically", false], ["Chlorine \u2014 used to disinfect the remaining water", false]], "q": "What useful product is obtained from anaerobic digestion of sewage sludge?", "wrong_explanations": {"1": "Distillation is used to purify water, not to treat sludge \u2014 the anaerobic digestion process produces GAS, not water.", "2": "Anaerobic digestion of sludge produces BOTH biogas AND digestate (solid fertiliser) \u2014 the gas is a key economic benefit.", "3": "Chlorine is added separately at the end of water treatment \u2014 it is not produced during anaerobic digestion."}}], "TH": [{"opts": [["Potable water contains low levels of dissolved minerals and is safe to drink \u2014 pure water contains only H\u2082O molecules", true], ["Potable water has been boiled \u2014 pure water has not been heated", false], ["Pure water is safe to drink \u2014 potable water contains pollutants", false], ["Potable water is seawater that has been filtered \u2014 pure water comes from rainfall only", false]], "q": "Why is potable water NOT the same as pure water?", "wrong_explanations": {"1": "Boiling is used in distillation to purify water \u2014 but potable water is not defined by whether it has been boiled.", "2": "It's the other way round \u2014 PURE water is chemically pure (H\u2082O only). POTABLE water is safe to drink but contains minerals.", "3": "Potable water comes from rivers, reservoirs, boreholes \u2014 not primarily seawater. Pure water is the chemically pure form."}}, {"opts": [["Biogas (mainly methane) \u2014 can be used as a renewable fuel", true], ["Pure water \u2014 the sludge is distilled", false], ["Fertiliser only \u2014 no gas is produced anaerobically", false], ["Chlorine \u2014 used to disinfect the remaining water", false]], "q": "What useful product is obtained from anaerobic digestion of sewage sludge?", "wrong_explanations": {"1": "Distillation is used to purify water, not to treat sludge \u2014 the anaerobic digestion process produces GAS, not water.", "2": "Anaerobic digestion of sludge produces BOTH biogas AND digestate (solid fertiliser) \u2014 the gas is a key economic benefit.", "3": "Chlorine is added separately at the end of water treatment \u2014 it is not produced during anaerobic digestion."}}]}, "rp": "RP8 (Chemistry) \u2014 Analysis and purification of water samples from different sources, including testing for pH, dissolved ions (using flame tests or precipitation) and filtering/distillation.", "summary": "Describe how potable water is produced and how waste water is treated.", "theory": [{"content": "POTABLE WATER is water that is SAFE TO DRINK \u2014 it has sufficiently low levels of dissolved substances and microbes.\n\nPotable water is NOT the same as PURE water:\nPure water contains ONLY H\u2082O molecules \u2014 no dissolved salts, minerals, microbes.\nPotable water contains low but acceptable levels of dissolved minerals \u2014 which are actually needed for good health (calcium, magnesium, fluoride etc.).\n\nGLOBAL WATER AVAILABILITY:\nOnly ~3% of Earth's water is freshwater.\nOf this, most is locked in ice caps \u2014 less than 1% is accessible freshwater.\nWater scarcity affects billions of people.\n\nSOURCES OF WATER IN THE UK:\nSURFACE WATER \u2014 rivers, lakes, reservoirs.\nGROUND WATER \u2014 aquifers underground, accessed by wells and boreholes.\nSEAWATER \u2014 can be desalinated (expensive and energy-intensive).", "heading": "Potable Water"}, {"content": "UK fresh water treatment process:\n\nSTEP 1 \u2014 SEDIMENTATION:\nWater flows into large settling tanks.\nLarge particles and suspended solids SINK to the bottom (sedimentation).\nAlternatively, a coagulant (e.g. aluminium sulfate) is added \u2192 particles clump together (flocculation) \u2192 settle faster.\n\nSTEP 2 \u2014 FILTRATION:\nWater passes through sand and gravel filters.\nRemoves finer particles and some microorganisms.\n\nSTEP 3 \u2014 CHLORINATION:\nSmall amounts of CHLORINE (or ozone/UV) added to kill harmful microorganisms (bacteria, viruses).\nChlorine is very effective and maintains protection as water travels through pipes.\n\nRESULT: potable water \u2014 not pure, but safe to drink.\n\nPURIFYING SEAWATER \u2014 DESALINATION:\nTWO METHODS:\n1. DISTILLATION \u2014 boil seawater, condense steam \u2192 pure water. Expensive (high energy).\n2. REVERSE OSMOSIS \u2014 force seawater through membranes that block dissolved salts. Energy-intensive.\nUsed in water-scarce regions (Middle East, some islands).\nNot widely used in UK \u2014 cheaper freshwater sources available.", "heading": "Treating Fresh Water to Make it Potable"}, {"content": "WASTE WATER includes:\nSEWAGE \u2014 water from toilets, drains, containing human waste, bacteria, organic matter.\nAGRICULTURAL WASTE \u2014 nitrates, pesticides.\nINDUSTRIAL WASTE \u2014 may contain heavy metals, chemicals.\n\nMust be treated before being released back into rivers or the sea.\n\nSEWAGE TREATMENT PROCESS:\n\nSTEP 1 \u2014 SCREENING:\nLarge solids removed by screens/grilles.\n\nSTEP 2 \u2014 SEDIMENTATION:\nRemaining solids sink to form SLUDGE.\nLiquid (effluent) is separated.\n\nSTEP 3 \u2014 BIOLOGICAL TREATMENT:\nEffluent undergoes AEROBIC DIGESTION \u2014 air is pumped through, aerobic bacteria break down organic matter \u2192 CO\u2082 + H\u2082O.\nSome plants also use anaerobic digestion.\n\nSTEP 4 \u2014 SLUDGE TREATMENT:\nSLUDGE undergoes ANAEROBIC DIGESTION \u2014 bacteria digest organic matter WITHOUT oxygen.\nProduces BIOGAS (mainly methane) \u2014 can be used as fuel.\nRemaining solids (digestate) can be used as fertiliser.\n\nFINAL STEP \u2014 CHLORINATION:\nEffluent disinfected with chlorine before discharge to rivers/sea.", "heading": "Waste Water Treatment"}]};
window.KS4SRC["radioactive-decay"] = {"common_mistake": "Alpha is the MOST ionising but LEAST penetrating. Gamma is the LEAST ionising per path length but MOST penetrating. These are often confused. Alpha is most dangerous INSIDE the body; gamma is most dangerous OUTSIDE the body.", "key_note": "\u03b1: helium nucleus (+2), stopped by paper, most ionising. \u03b2: fast electron (\u22121), stopped by aluminium, moderate. \u03b3: EM wave (0 charge), needs lead/concrete, least ionising per path. Activity in Bq. Decay is random. Uses: smoke detectors (\u03b1), thickness gauges (\u03b2), cancer treatment/sterilisation (\u03b3).", "matching": {"instruction": "Match each radiation type to its composition, penetration and use.", "pairs": [["Alpha (\u03b1)", "Helium nucleus \u2014 stopped by paper \u2014 used in smoke detectors"], ["Beta (\u03b2)", "Fast electron \u2014 stopped by aluminium \u2014 used in paper thickness monitoring"], ["Gamma (\u03b3)", "EM wave \u2014 needs lead/concrete \u2014 used in cancer radiotherapy and sterilisation"], ["Most ionising", "Alpha radiation \u2014 causes most ion pairs per cm of path"], ["Most penetrating", "Gamma radiation \u2014 passes through most materials, needs lead/concrete shielding"]], "title": "Radiation Properties"}, "quiz": {"CF": [{"opts": [["Alpha is highly ionising \u2014 it causes dense ionisation damage to nearby cells and cannot escape the body to be detected", true], ["Alpha has the highest energy of all three types \u2014 more energy means more damage", false], ["Alpha moves fastest \u2014 it collides more often with cells", false], ["Alpha is most penetrating \u2014 it reaches all organs from a single source", false]], "q": "Why is alpha radiation the most dangerous type when a source is inside the body?", "wrong_explanations": {"1": "Alpha does not have the highest energy \u2014 gamma photons have very high energies too. The danger is from DENSE IONISATION in a small area.", "2": "Alpha is actually the SLOWEST of the three \u2014 and its high mass means it interacts strongly with matter.", "3": "Alpha is the LEAST penetrating \u2014 stopped by a few cm of air. That's exactly why it's so dangerous inside the body \u2014 all ionisation is deposited nearby."}}, {"opts": [["340 nuclei in the source are decaying every second, each emitting radiation", true], ["The source has 340 radioactive atoms remaining in total", false], ["The source emits 340 joules of energy every second", false], ["The source has been decaying for 340 seconds", false]], "q": "A Geiger counter measures 340 Bq from a radioactive source. What does this mean?", "wrong_explanations": {"1": "Activity = total number of radioactive atoms remaining, not the rate. Bq measures the RATE of decay (per second).", "2": "Bq measures rate in decays per second \u2014 not joules. Energy per decay is measured in eV or joules, not Bq.", "3": "Bq is a rate (per second) \u2014 not a duration."}}], "CH": [{"opts": [["Alpha is highly ionising \u2014 it causes dense ionisation damage to nearby cells and cannot escape the body to be detected", true], ["Alpha has the highest energy of all three types \u2014 more energy means more damage", false], ["Alpha moves fastest \u2014 it collides more often with cells", false], ["Alpha is most penetrating \u2014 it reaches all organs from a single source", false]], "q": "Why is alpha radiation the most dangerous type when a source is inside the body?", "wrong_explanations": {"1": "Alpha does not have the highest energy \u2014 gamma photons have very high energies too. The danger is from DENSE IONISATION in a small area.", "2": "Alpha is actually the SLOWEST of the three \u2014 and its high mass means it interacts strongly with matter.", "3": "Alpha is the LEAST penetrating \u2014 stopped by a few cm of air. That's exactly why it's so dangerous inside the body \u2014 all ionisation is deposited nearby."}}, {"opts": [["340 nuclei in the source are decaying every second, each emitting radiation", true], ["The source has 340 radioactive atoms remaining in total", false], ["The source emits 340 joules of energy every second", false], ["The source has been decaying for 340 seconds", false]], "q": "A Geiger counter measures 340 Bq from a radioactive source. What does this mean?", "wrong_explanations": {"1": "Activity = total number of radioactive atoms remaining, not the rate. Bq measures the RATE of decay (per second).", "2": "Bq measures rate in decays per second \u2014 not joules. Energy per decay is measured in eV or joules, not Bq.", "3": "Bq is a rate (per second) \u2014 not a duration."}}], "TF": [{"opts": [["Alpha is highly ionising \u2014 it causes dense ionisation damage to nearby cells and cannot escape the body to be detected", true], ["Alpha has the highest energy of all three types \u2014 more energy means more damage", false], ["Alpha moves fastest \u2014 it collides more often with cells", false], ["Alpha is most penetrating \u2014 it reaches all organs from a single source", false]], "q": "Why is alpha radiation the most dangerous type when a source is inside the body?", "wrong_explanations": {"1": "Alpha does not have the highest energy \u2014 gamma photons have very high energies too. The danger is from DENSE IONISATION in a small area.", "2": "Alpha is actually the SLOWEST of the three \u2014 and its high mass means it interacts strongly with matter.", "3": "Alpha is the LEAST penetrating \u2014 stopped by a few cm of air. That's exactly why it's so dangerous inside the body \u2014 all ionisation is deposited nearby."}}, {"opts": [["340 nuclei in the source are decaying every second, each emitting radiation", true], ["The source has 340 radioactive atoms remaining in total", false], ["The source emits 340 joules of energy every second", false], ["The source has been decaying for 340 seconds", false]], "q": "A Geiger counter measures 340 Bq from a radioactive source. What does this mean?", "wrong_explanations": {"1": "Activity = total number of radioactive atoms remaining, not the rate. Bq measures the RATE of decay (per second).", "2": "Bq measures rate in decays per second \u2014 not joules. Energy per decay is measured in eV or joules, not Bq.", "3": "Bq is a rate (per second) \u2014 not a duration."}}], "TH": [{"opts": [["Alpha is highly ionising \u2014 it causes dense ionisation damage to nearby cells and cannot escape the body to be detected", true], ["Alpha has the highest energy of all three types \u2014 more energy means more damage", false], ["Alpha moves fastest \u2014 it collides more often with cells", false], ["Alpha is most penetrating \u2014 it reaches all organs from a single source", false]], "q": "Why is alpha radiation the most dangerous type when a source is inside the body?", "wrong_explanations": {"1": "Alpha does not have the highest energy \u2014 gamma photons have very high energies too. The danger is from DENSE IONISATION in a small area.", "2": "Alpha is actually the SLOWEST of the three \u2014 and its high mass means it interacts strongly with matter.", "3": "Alpha is the LEAST penetrating \u2014 stopped by a few cm of air. That's exactly why it's so dangerous inside the body \u2014 all ionisation is deposited nearby."}}, {"opts": [["340 nuclei in the source are decaying every second, each emitting radiation", true], ["The source has 340 radioactive atoms remaining in total", false], ["The source emits 340 joules of energy every second", false], ["The source has been decaying for 340 seconds", false]], "q": "A Geiger counter measures 340 Bq from a radioactive source. What does this mean?", "wrong_explanations": {"1": "Activity = total number of radioactive atoms remaining, not the rate. Bq measures the RATE of decay (per second).", "2": "Bq measures rate in decays per second \u2014 not joules. Energy per decay is measured in eV or joules, not Bq.", "3": "Bq is a rate (per second) \u2014 not a duration."}}]}, "summary": "Describe alpha, beta and gamma radiation, their properties and uses and dangers.", "theory": [{"content": "Some atomic nuclei are UNSTABLE \u2014 they spontaneously emit radiation to become more stable.\nThis is RADIOACTIVE DECAY \u2014 a RANDOM process (cannot predict exactly when any nucleus will decay).\n\nACTIVITY: the rate at which a source decays \u2014 measured in BECQUEREL (Bq).\n1 Bq = 1 decay per second.\n\nCOUNT RATE: decays recorded per second by a detector (e.g. Geiger-M\u00fcller tube).\n\nThree main types of nuclear radiation:\nALPHA (\u03b1) \u2014 helium nucleus (2 protons + 2 neutrons)\nBETA (\u03b2) \u2014 fast electron from the nucleus\nGAMMA (\u03b3) \u2014 high-energy electromagnetic wave", "heading": "Radioactive Decay"}, {"content": "ALPHA (\u03b1):\nComposition: 2 protons + 2 neutrons (helium-4 nucleus, \u2074\u2082He)\nCharge: +2\nMass: 4 amu\nRange in air: a few centimetres\nPenetration: stopped by a few cm of air, or paper, or skin\nIonisation: STRONGLY ionising \u2014 causes most damage to nearby cells\n\nBETA (\u03b2):\nComposition: fast-moving electron (\u2070\u208b\u2081e)\nCharge: \u22121\nMass: negligible\nRange in air: a few metres\nPenetration: stopped by a few mm of aluminium\nIonisation: moderately ionising\n\nGAMMA (\u03b3):\nComposition: high-energy electromagnetic wave (photon)\nCharge: 0\nMass: 0\nRange in air: effectively unlimited\nPenetration: reduced by several cm of lead or metres of concrete\nIonisation: weakly ionising per unit path\n\nDETECTION: Geiger-M\u00fcller tube connected to a counter.", "heading": "Properties of Alpha, Beta and Gamma"}, {"content": "USES:\nALPHA \u2014 smoke detectors: alpha source ionises air \u2192 current flows \u2192 alarm triggers when smoke absorbs alpha and current drops.\nBETA \u2014 paper thickness monitoring: beta passes through paper; more absorbed = thicker paper \u2192 adjust rollers.\nGAMMA \u2014 medical imaging (gamma cameras), cancer treatment (radiotherapy), sterilising medical equipment, food irradiation.\nGAMMA/BETA \u2014 industrial thickness gauges, pipeline fault detection.\n\nDANGERS:\nAll ionising radiation damages living cells by ionising molecules in DNA \u2192 mutations \u2192 cancer.\nHIGH DOSE \u2192 cell death \u2192 radiation sickness.\nALPHA: most dangerous INSIDE the body (highly ionising, can't escape). Safe outside the body (stopped by skin).\nGAMMA: most dangerous OUTSIDE the body (penetrates to internal organs). Less ionising per path length.\nBETA: intermediate \u2014 penetrates skin, absorbed by soft tissue.\n\nPROTECTION:\nDistance \u2014 inverse square law applies (intensity decreases with distance).\nShielding \u2014 appropriate materials (paper for alpha, aluminium for beta, lead for gamma).\nTime \u2014 minimise exposure duration.\nMonitoring \u2014 dosimeters worn by radiation workers.", "heading": "Uses and Dangers of Nuclear Radiation"}]};
window.KS4SRC["red-shift-big-bang"] = {"common_mistake": "Red-shift does NOT mean galaxies are moving THROUGH space away from us \u2014 it means SPACE ITSELF is expanding between galaxies. The Earth is not at the centre of the universe \u2014 all observers in any galaxy would see other galaxies receding. The Big Bang was not an explosion in an existing space \u2014 it was the beginning of space and time itself.", "equations": ["v = H\u2080 \u00d7 d  (Hubble's Law)"], "higher": "Apply Hubble's Law: v = H\u2080d. Calculate recession speed from red-shift data. Explain how CMBR is strong evidence for the Big Bang. Evaluate the significance of dark matter and dark energy for the Big Bang model and the future of the universe.", "key_note": "Red-shift: distant galaxies' light stretched to longer wavelengths \u2192 moving away \u2192 universe expanding. Hubble's Law: v = H\u2080d (faster recession = further away). Big Bang: ~13.8 billion years ago, hot dense singularity. Evidence: red-shift, CMBR (2.7 K microwave background), H/He abundance. CMBR = strongest evidence.", "matching": {"instruction": "Match each piece of evidence to the Big Bang theory.", "pairs": [["Red-shift of galaxies", "Nearly all galaxies moving away \u2014 greater red-shift for more distant galaxies \u2014 universe expanding"], ["Cosmic Microwave Background Radiation", "Faint microwave radiation from all directions \u2014 afterglow of the hot early universe at 2.7 K"], ["H/He abundance", "~75% hydrogen, ~25% helium \u2014 matches Big Bang nucleosynthesis predictions"], ["Hubble's Law", "Recession speed \u221d distance (v = H\u2080d) \u2014 first observational evidence for expansion"]], "title": "Evidence for the Big Bang"}, "quiz": {"TF": [{"opts": [["The universe is expanding \u2014 all distant galaxies are moving away, with more distant galaxies receding faster (Hubble's Law)", true], ["Distant galaxies are very hot \u2014 the red colour indicates high temperature", false], ["The universe is rotating \u2014 galaxies on the far side are moving away as it spins", false], ["Distant galaxies are all moving towards a common point \u2014 the universe is contracting", false]], "q": "What does the red-shift of distant galaxies tell us about the universe?", "wrong_explanations": {"1": "Red-shift is not about colour of the galaxy \u2014 it's a Doppler shift in ALL wavelengths of light from the galaxy, indicating recession velocity.", "2": "If the universe were rotating, we'd expect some galaxies to show red-shift and others blue-shift depending on direction. Nearly ALL show red-shift.", "3": "Red-shift means AWAY from us \u2014 if galaxies were all moving toward a common point, we'd see blue-shift from most directions."}}, {"opts": [["It is a faint, uniform microwave glow from all directions \u2014 exactly matching the predicted afterglow of the hot early universe cooled to ~2.7 K by 13.8 billion years of expansion", true], ["It shows that microwaves existed before the Big Bang \u2014 proving the universe had a beginning", false], ["It provides a current map of where all galaxies are moving \u2014 confirming Hubble's Law", false], ["It was predicted after the Big Bang theory was developed \u2014 making it a confirmatory test rather than a coincidence", false]], "q": "Why is the Cosmic Microwave Background Radiation (CMBR) considered the strongest evidence for the Big Bang?", "wrong_explanations": {"1": "The CMBR is evidence OF the Big Bang, not evidence for events BEFORE it \u2014 there is no observable evidence from before the Big Bang.", "2": "The CMBR shows the distribution of early universe temperature fluctuations \u2014 it maps the early universe, not galaxy motion today.", "3": "The strength of the CMBR as evidence is that it was PREDICTED by the Big Bang theory and then discovered independently \u2014 the prediction of its temperature and uniformity is confirmed by observation."}}], "TH": [{"opts": [["The universe is expanding \u2014 all distant galaxies are moving away, with more distant galaxies receding faster (Hubble's Law)", true], ["Distant galaxies are very hot \u2014 the red colour indicates high temperature", false], ["The universe is rotating \u2014 galaxies on the far side are moving away as it spins", false], ["Distant galaxies are all moving towards a common point \u2014 the universe is contracting", false]], "q": "What does the red-shift of distant galaxies tell us about the universe?", "wrong_explanations": {"1": "Red-shift is not about colour of the galaxy \u2014 it's a Doppler shift in ALL wavelengths of light from the galaxy, indicating recession velocity.", "2": "If the universe were rotating, we'd expect some galaxies to show red-shift and others blue-shift depending on direction. Nearly ALL show red-shift.", "3": "Red-shift means AWAY from us \u2014 if galaxies were all moving toward a common point, we'd see blue-shift from most directions."}}, {"opts": [["It is a faint, uniform microwave glow from all directions \u2014 exactly matching the predicted afterglow of the hot early universe cooled to ~2.7 K by 13.8 billion years of expansion", true], ["It shows that microwaves existed before the Big Bang \u2014 proving the universe had a beginning", false], ["It provides a current map of where all galaxies are moving \u2014 confirming Hubble's Law", false], ["It was predicted after the Big Bang theory was developed \u2014 making it a confirmatory test rather than a coincidence", false]], "q": "Why is the Cosmic Microwave Background Radiation (CMBR) considered the strongest evidence for the Big Bang?", "wrong_explanations": {"1": "The CMBR is evidence OF the Big Bang, not evidence for events BEFORE it \u2014 there is no observable evidence from before the Big Bang.", "2": "The CMBR shows the distribution of early universe temperature fluctuations \u2014 it maps the early universe, not galaxy motion today.", "3": "The strength of the CMBR as evidence is that it was PREDICTED by the Big Bang theory and then discovered independently \u2014 the prediction of its temperature and uniformity is confirmed by observation."}}]}, "summary": "Explain red-shift as evidence for an expanding universe and describe the Big Bang theory.", "theory": [{"content": "RED-SHIFT: light from distant galaxies is shifted towards LONGER WAVELENGTHS (red end of the spectrum).\n\nThis is a DOPPLER EFFECT \u2014 similar to how a siren sounds lower-pitched as an ambulance drives away.\nWhen a light source moves AWAY from an observer, wavelengths are STRETCHED \u2192 shifted to red.\nWhen a light source moves TOWARDS an observer, wavelengths are COMPRESSED \u2192 blue-shift.\n\nOBSERVATIONS:\nNearly all galaxies show red-shift \u2192 nearly all galaxies are moving AWAY from us.\nMore distant galaxies show GREATER red-shift \u2192 moving away FASTER.\nThis relationship (velocity proportional to distance) was discovered by Edwin Hubble (1929) \u2014 HUBBLE'S LAW.\n\nHUBBLE'S LAW:\nRecession speed = Hubble constant \u00d7 distance\nv = H\u2080 \u00d7 d\n\nH\u2080 \u2248 70 km/s/Mpc (current best estimate).\n\nKEY CONCLUSION:\nThe universe is EXPANDING \u2014 all galaxies moving away from all others.", "heading": "Red-shift"}, {"content": "The expanding universe implies that in the past, all matter was closer together.\nExtrapolating backwards \u2192 there was a point in time when all matter and energy was concentrated in an incredibly hot, dense state \u2014 THE BIG BANG.\n\nBIG BANG TIMELINE:\n~13.8 billion years ago: Big Bang \u2014 universe begins from an extremely hot, dense singularity.\nFirst 380,000 years: universe too hot for neutral atoms \u2014 opaque plasma.\n380,000 years: universe cools enough for hydrogen atoms to form \u2192 universe becomes transparent.\nFirst light (CMBR emitted).\nHundreds of millions of years: first stars and galaxies form.\n~4.6 billion years ago: Solar System forms.\n~3.8 billion years ago: life on Earth begins.\nNow: observable universe ~93 billion light-years in diameter.\n\nIMPORTANT: The Big Bang was not an explosion IN space \u2014 it was an expansion OF space itself. There is no centre of the universe \u2014 all points are moving away from all others.", "heading": "The Big Bang Theory"}, {"content": "EVIDENCE FOR THE BIG BANG:\n\n1. RED-SHIFT OF GALAXIES:\nAll distant galaxies show red-shift \u2014 moving away.\nMore distant \u2192 greater red-shift \u2192 faster recession (Hubble's Law).\nFirst and most direct evidence for expansion.\n\n2. COSMIC MICROWAVE BACKGROUND RADIATION (CMBR):\nFaint microwave radiation detected uniformly from all directions.\nPredicted by Big Bang theory \u2014 the afterglow of the hot early universe, now cooled to ~2.7 K.\nDiscovered accidentally by Penzias and Wilson (1964) \u2014 confirmed the Big Bang.\nThe most compelling evidence for the Big Bang theory.\n\n3. ABUNDANCE OF HYDROGEN AND HELIUM:\nBig Bang nucleosynthesis predicted ~75% hydrogen, ~25% helium (by mass).\nObservations of the oldest stars match this prediction remarkably well.\n\n4. LARGE-SCALE STRUCTURE:\nThe distribution of galaxies in the universe matches the predicted evolution from the Big Bang.\n\nUNANSWERED QUESTIONS:\nDark matter: ~27% of universe's mass-energy is 'dark matter' \u2014 does not interact with light.\nDark energy: ~68% \u2014 mysterious energy causing accelerating expansion.\nOriginal cause of the Big Bang remains unknown.", "heading": "Evidence for an Expanding Universe"}], "variables": [["v", "Recession speed", "km/s", "km/s"], ["H\u2080", "Hubble constant", "km/s/Mpc", "km/s/Mpc"], ["d", "Distance to galaxy", "Mpc", "Mpc"]]};
